#!/usr/bin/env python3
"""Generate question files for each subelement from the 2026-2030 pool JSON.

Reads pools/2026-2030/questions.json and outputs one markdown file per
subelement into subelements/, matching the existing study-guide format.
"""

import json
import re
import sys
from pathlib import Path
from collections import defaultdict

REPO = Path(__file__).resolve().parent.parent
POOL_PATH = REPO / "pools" / "2026-2030" / "questions.json"
OUTPUT_DIR = REPO / "subelements"

# Mapping of subelement IDs to output filenames (stem only)
SUBELEMENT_FILES = {
    "T0": "T0-safety",
    "T1": "T1-fcc-rules",
    "T2": "T2-operating-procedures",
    "T3": "T3-radio-waves",
    "T4": "T4-amateur-practices",
    "T5": "T5-electrical-principles",
    "T6": "T6-components",
    "T7": "T7-practical-circuits",
    "T8": "T8-signals-emissions",
    "T9": "T9-antennas-feedlines",
}

# Group titles from the official NCVEC 2026-2030 Technician syllabus
GROUP_DESCRIPTIONS = {
    "T0A": "Power circuits and hazards: hazardous voltages, fuses and circuit breakers, grounding, electrical code compliance; Lightning protection; Battery safety",
    "T0B": "Antenna safety: tower safety and grounding, installing antennas, antenna supports",
    "T0C": "RF hazards: radiation exposure, proximity to antennas, recognized safe power levels, radiation types, duty cycle",
    "T1A": "Purpose and permissible use of the Amateur Radio Service; Operator/primary station license grant; Meanings of basic terms used in FCC rules; Interference; RACES rules; Phonetics; Frequency Coordinator; Beacon",
    "T1B": "Frequency allocations; Emission modes; Spectrum sharing; Transmissions near band edges; Contacting the International Space Station; Power output",
    "T1C": "Licensing: classes, sequential and vanity call sign systems, places where the Amateur Radio Service is regulated by the FCC, name and address on FCC license database, term, renewal, grace period, maintaining mailing address; International communications",
    "T1D": "Authorized and prohibited transmissions; Sale of equipment",
    "T1E": "Control operator: eligibility, designating, privileges, duties, location, required; Control point; Control types: automatic, remote",
    "T1F": "Station identification; Repeaters; Third-party communications; Club stations; FCC inspection",
    "T2A": "Station operation: choosing an operating frequency, calling another station, test transmissions; Band plans: calling frequencies, repeater offsets",
    "T2B": "VHF/UHF operating practices: FM repeater, simplex, reverse splits; Access tones: CTCSS, DTMF; DMR operation; Resolving operating problems; Q signals",
    "T2C": "Public service: emergency operations, applicability of FCC rules, RACES and ARES, net and traffic procedures, operating restrictions during emergencies, use of phonetics in message handling",
    "T3A": "Radio wave characteristics: how a radio signal travels, fading, multipath, polarization, wavelength vs absorption; Antenna orientation",
    "T3B": "Electromagnetic wave properties: wavelength vs frequency, nature and velocity of electromagnetic waves, relationship of wavelength and frequency; Electromagnetic Spectrum Definitions: UHF, VHF, HF",
    "T3C": "Propagation modes: sporadic E, meteor scatter, auroral propagation, tropospheric ducting; F region skip; Line of sight and radio horizon",
    "T4A": "Station setup: connecting a microphone, RF power meter, a power source, a computer, digital equipment, an SWR meter; RF grounding; Mobile radio installation",
    "T4B": "Operating controls: frequency tuning, use of filters, squelch function, AGC, memory channels, noise blanker, microphone gain, receiver incremental tuning (RIT), bandwidth selection, scanning function; Digital transceiver configuration; DMR code plugs and talk groups",
    "T5A": "Current and voltage: terminology and units, conductors and insulators, alternating and direct current",
    "T5B": "Math for electronics: conversion of electrical units, decibels",
    "T5C": "Capacitance and inductance terminology and units; Radio frequency definition and units; Impedance definition and units; Calculating power",
    "T5D": "Ohm's Law; Series and parallel circuits",
    "T6A": "Fixed and variable resistors; Capacitors; Inductors; Fuses; Switches; Batteries",
    "T6B": "Semiconductors: basic principles and applications of solid-state devices, diodes and transistors; Gain",
    "T6C": "Circuit diagrams: use of term schematic, basic structure; Schematic symbols of basic components",
    "T6D": "Component functions: rectifiers, relays, voltage regulators, meters, indicators, integrated circuits, transformers; Resonant circuit; Shielding",
    "T7A": "Station equipment: receivers, transceivers, transmitter amplifiers, RF preamplifiers, transverters; Basic radio circuit concepts and terminology: sensitivity, selectivity, mixers, oscillators, Push-To-Talk (PTT), VFO, modulation",
    "T7B": "Symptoms, causes, and cures of common transmitter and receiver problems: overload and overdrive, distortion, interference and consumer electronics, RF feedback",
    "T7C": "Antenna and transmission line measurements and troubleshooting: measuring SWR, effects of high SWR, causes of feed line failures; Basic coaxial cable characteristics; Use of dummy loads when testing",
    "T7D": "Using basic test instruments: voltmeter, ammeter, and ohmmeter; Soldering",
    "T8A": "Basic characteristics of FM and SSB; Bandwidth of various modulation modes: CW, SSB, FM, fast-scan TV; Choice of emission type: selection of USB vs LSB, use of SSB for weak signal work, use of FM for VHF packet and repeaters",
    "T8B": "Amateur satellite operation: Doppler shift, basic orbits, operating protocols, modulation mode selection, transmitter power considerations, telemetry, satellite tracking programs, beacons, uplink and downlink mode definitions, spin fading, definition of “LEO”, setting uplink power",
    "T8C": "Operating activities: radio direction finding, contests, linking over the internet, exchanging grid locators",
    "T8D": "Non-voice and digital communications: image signals and definition of NTSC, CW, packet radio, PSK, APRS, error detection and correction, amateur radio networking, DMR, WSJT modes, Broadband-Hamnet",
    "T9A": "Antennas: vertical and horizontal polarization, concept of antenna gain, definition and types of beam antennas, antenna loading, common portable and mobile antennas, relationships between resonant length and frequency, dipole pattern",
    "T9B": "Feed lines: types, attenuation vs frequency, selecting; SWR concepts; Antenna tuners (couplers); RF Connectors: selecting, weather protection",
}

# ── Explanation generator ────────────────────────────────────────────
# Hand-written explanations for every question in the 2026-2030 pool.
# Key = question ID, value = explanation paragraph.

EXPLANATIONS: dict[str, str] = {}

# Questions whose legacy explanation text is off-topic for the 2026-2030 pool.
# These IDs intentionally fall back to a generated explanation that always
# matches the current question/answer pair.
FALLBACK_EXPLANATION_IDS: set[str] = set()


def _load_explanations() -> None:
    """Populate the EXPLANATIONS dict.

    The explanations are defined inline below rather than in a separate
    data file so the script is fully self-contained.
    """
    # fmt: off
    E = EXPLANATIONS

    # ── T0A ──────────────────────────────────────────────────────────
    E["T0A01"] = "While 12 volts won't shock you through dry skin (your body's resistance is too high), a 12-volt battery without internal protection can deliver hundreds of amps if shorted, melting wires, causing burns, and potentially igniting hydrogen gas. The danger is massive current, not voltage."
    E["T0A02"] = "Electrical current through the body causes all three hazards: tissue heating (burns), disruption of cellular electrical functions (cardiac arrest, nerve damage), and involuntary muscle contractions (which can prevent you from letting go of the source). Even small currents through the heart can be fatal."
    E["T0A03"] = "In US wiring: Black = Hot (dangerous), White = Neutral, Green or bare = Ground. The black wire carries the full 120V AC potential and is the most dangerous conductor. The National Electrical Code requires white or gray for neutral and green or bare for ground; black for hot is the standard convention. Memorize it."
    E["T0A04"] = "A fuse opens (blows) when current exceeds its rating, disconnecting the circuit to prevent fire and equipment damage from overloads. It protects wiring and equipment — it does NOT prevent shock (the current needed to kill you is far below a typical fuse rating)."
    E["T0A05"] = "A 20-amp fuse would allow four times the designed current to flow through wiring rated for only 5 amps. The wires overheat and can start a fire before the fuse ever blows. Always replace fuses with the same rating — never larger. This is a fundamental fire safety rule."
    E["T0A06"] = "All three are essential safety practices. Three-wire plugs provide equipment grounding, a common safety ground prevents dangerous voltage differences between equipment, and ensuring high-voltage capacitors are discharged before opening equipment prevents lethal shocks. Layered safety is the best approach."
    E["T0A07"] = "Lightning arresters go where the feed line enters the building, mounted on a grounded panel. This stops lightning energy at the building entry point before it can enter your shack. Placing it at the radio or antenna wouldn't protect the building wiring and equipment between those points."
    E["T0A08"] = "The fuse goes in series with the hot (black) wire only. Fusing the neutral wire could create a dangerous condition where equipment appears de-energized but the hot wire is still live. A fuse in parallel would short-circuit the power line. Series with hot only = safe interruption."
    E["T0A09"] = "All ground rods must be bonded together to create a single ground system with no voltage differences between rods. During a lightning strike, separate unbonded grounds can have dangerous voltage differences. Bond everything together — electrical panel ground, radio ground, tower ground — into one unified system."
    E["T0A10"] = "Rapidly charging or discharging a battery without built-in protection generates excessive heat and can cause the battery to vent gas (out-gassing). In sealed batteries, this pressure buildup can cause rupture or explosion. Lead-acid and lithium batteries are both susceptible. Always use appropriate charge rates and batteries with proper protection."
    E["T0A11"] = "Large filter capacitors in power supplies can hold lethal voltages for minutes or even hours after the supply is turned off. Always treat a recently powered-off power supply as dangerous. High-voltage capacitors must be safely discharged before working on equipment. This has killed many technicians."
    E["T0A12"] = "Using a meter or leads not rated for the voltage being measured can result in arcing, insulation breakdown, and electrocution. Always check that both the meter and the probes are rated for the voltages involved. Many meters are rated only up to 600 or 1000 volts, so the higher voltages in some amplifiers need a high-voltage probe rated for that voltage. Low impedance meters would actually draw excessive current — you want high impedance."

    # ── T0B ──────────────────────────────────────────────────────────
    E["T0B01"] = "Lightning ground connections must be short and direct — long, winding paths have too much inductance for lightning's fast-rising pulse. Sharp right-angle bends are bad because they impede current flow and can cause arcing. Drip loops are irrelevant for grounding. Think: shortest path to earth."
    E["T0B02"] = "Tower climbing requires all three: proper training, continuous tie-off (always attached to the tower, moving one lanyard at a time), and an approved harness. Falls from towers are frequently fatal. This isn't optional safety gear — it's all mandatory. Many amateur radio operators have died from tower falls."
    E["T0B03"] = "Never climb a tower alone. Always have a ground observer who can call for help if you fall or become incapacitated. There are NO exceptions to this rule — not height, not task type, not experience level. A fall at 10 feet can kill you just as dead as one at 100 feet."
    E["T0B04"] = "Contact with overhead power lines during tower installation is one of the most common causes of amateur radio fatalities. A tower, antenna, or guy wire touching a power line is instantly lethal. Always survey for power lines before any antenna work. Never insulate a tower base — it should be grounded."
    E["T0B05"] = "Wind and vibration can gradually unscrew turnbuckles, loosening guy wires and potentially toppling the tower. A safety wire through the turnbuckle body prevents it from turning. This simple precaution can prevent catastrophic tower failure."
    E["T0B06"] = "The rule is clear: if the antenna falls in any direction, no part should be able to come within 10 feet of power lines. This accounts for the antenna's full height and reach when it falls. Power line contact kills — maintain clearance even in a worst-case scenario."
    E["T0B07"] = "Crank-up towers can collapse if the cable or winch fails. Never climb one unless it's fully retracted or has mechanical safety locks engaged. The locking devices prevent the sections from telescoping down on you — without them, the tower is a guillotine. Crank-up towers should absolutely be grounded and can be painted."
    E["T0B08"] = "Proper tower grounding requires separate 8-foot ground rods at each leg, all bonded together and to the tower. Four-foot rods are too short, single rods are insufficient, ferrite chokes are for RF not lightning, and a cold-water pipe alone isn't adequate for tower grounding."
    E["T0B09"] = "Utility poles carry high-voltage power lines. Attaching an antenna creates the risk of contact with those lines — during installation, wind, ice loading, or structural failure. This is potentially fatal. The other answers about induced voltages and unbalancing the power transformer are distractors."
    E["T0B10"] = "Lightning ground conductors should follow smooth, sweeping curves — sharp bends create high inductance points where lightning can arc across the bend rather than following the conductor. Common (shared) grounds are actually required, not avoided. Use the most direct path possible."
    E["T0B11"] = "Local electrical codes (based on the National Electrical Code) establish grounding requirements for amateur towers and antennas. FCC Part 97 covers radio rules, FAA covers tower lighting/marking for aviation safety, and UL tests equipment — none of these set grounding standards."

    # ── T0C ──────────────────────────────────────────────────────────
    E["T0C01"] = "Radio waves are non-ionizing radiation — they don't have enough energy to knock electrons from atoms or break chemical bonds. Gamma and alpha radiation are ionizing and can cause cellular damage and cancer. RF radiation can cause heating but not the DNA damage associated with ionizing radiation."
    E["T0C02"] = "The human body absorbs RF energy most efficiently in the 30–300 MHz range, where body size is close to resonant with the wavelength (adult whole-body resonance is roughly 35 to 70 MHz, depending on grounding). Because more energy is absorbed, the FCC maximum permissible exposure (MPE) limit is lowest across this whole range. Of the choices, only 50 MHz falls inside it; 3.5, 440, and 1296 MHz all have higher limits."
    E["T0C03"] = "At 50% duty cycle, you're only transmitting half the time, so average exposure is halved. This means you can use twice the power density while still meeting the same average exposure limits. Allowable power scales inversely with duty cycle: half the duty cycle = double the allowable power."
    E["T0C04"] = "RF exposure depends on all three: frequency (body absorption varies), power level (more power = more exposure), distance (far from the antenna, power density drops with the square of distance), and antenna pattern (a beam antenna concentrates energy in specific directions). All must be considered in an RF exposure evaluation."
    E["T0C05"] = "The human body's RF absorption is frequency-dependent. It peaks when body dimensions are close to resonant with the wavelength, roughly 35 to 70 MHz for an adult, which is why the limits are lowest from 30 to 300 MHz. At other frequencies, less energy is absorbed, so higher exposure levels are permitted. This is basic biophysics."
    E["T0C06"] = "The FCC accepts all three methods for demonstrating compliance: OET Bulletin 65 calculations, computer modeling, and actual field strength measurements. Most amateurs use the OET-65 calculation method since it doesn't require expensive measurement equipment."
    E["T0C07"] = "Touching a transmitting antenna causes RF burns — localized tissue heating at the contact point. This is different from electrocution, which comes from DC or low-frequency current, and from exposure to ionizing radiation, which causes DNA damage. RF burns can be severe and deep, damaging tissue beneath the skin surface."
    E["T0C08"] = "Moving antennas farther from people is the most effective way to reduce RF exposure, since, far from the antenna, power density drops with the square of distance. Moving just the transmitter doesn't help (the antenna is the source of radiation). Increasing duty cycle would increase exposure, not reduce it."
    E["T0C09"] = "Any change to your transmitter power, antenna type, height, or location could change the RF exposure profile. Re-evaluate compliance whenever the system changes. Low SWR helps efficiency but doesn't directly determine RF safety compliance, and just using UL-approved equipment doesn't guarantee safe exposure levels."
    E["T0C10"] = "Duty cycle determines what fraction of time you're actually transmitting, which directly affects average RF exposure over the evaluation period. Speaking on SSB (low duty cycle) produces much less average exposure than an FM carrier at the same power. RF safety limits are based on average exposure over time."
    E["T0C11"] = "Duty cycle is the percentage of time the transmitter is actively transmitting during the averaging period. CW has roughly 40–50% duty cycle, SSB voice about 20–40%, and FM is near 100% when the PTT is pressed. Note: it's the time transmitting, not the time NOT transmitting — watch for that trap."
    E["T0C12"] = "RF radiation lacks the energy to ionize atoms, break chemical bonds, or damage DNA — that's what makes it \"non-ionizing.\" Ionizing radiation (gamma, X-ray, alpha, beta) has enough energy to cause cellular and DNA damage. RF is NOT \"perfectly safe\" — it can cause thermal burns and tissue heating — but it doesn't cause the cellular damage that ionizing radiation does."
    E["T0C13"] = "The station licensee bears full responsibility for ensuring RF exposure compliance. It's YOUR license, YOUR station, YOUR responsibility. Not the FCC's job to check every station, not the public's job to protect themselves, and certainly not the zoning board's concern. You must evaluate and ensure compliance."

    # ── T1A ──────────────────────────────────────────────────────────
    E["T1A01"] = "The Amateur Radio Service exists to advance skills in the technical and communication phases of the radio art. It's not about providing personal radio for as many people as possible (that's more like CB radio), and it's not specifically about international contesting. The FCC's vision is about advancing radio knowledge."
    E["T1A02"] = "The FCC — the Federal Communications Commission — is the sole US agency that regulates and enforces the rules for amateur radio. Not the ARRL (that's a membership organization), not Homeland Security, and not the ITU (that's an international body). The FCC writes the rules and enforces them."
    E["T1A03"] = "The FCC encourages the use of a phonetic alphabet for station identification, but doesn't require it. You won't get in trouble for not using phonetics, but they help make your call sign clearer on the air, especially in noisy conditions. Encouraged, not mandatory."
    E["T1A04"] = "After you pass the exam, your official notification comes when the FCC emails you with a link to download your license grant from their Universal Licensing System (ULS). It's not mailed by USPS, and it doesn't come from the volunteer examiners — it comes directly from the FCC electronically."
    E["T1A05"] = "Your license appears in the FCC's ULS (Universal Licensing System) database, and that's when it's official. The Certificate of Successful Completion of Examination is just proof you passed the test — it's not the license itself. You can transmit as soon as your call sign shows up in ULS."
    E["T1A06"] = "Under 47 CFR 97.203(d), automatically controlled beacons on HF may only operate on ten meters, between 28.200 and 28.300 MHz. That is the only HF segment where U.S. automatically controlled beacons are permitted. FCC registration does not open other frequencies, and beacons are not allowed throughout the Technician 10 meter segment or in every Technician HF band."
    E["T1A07"] = "A space station in amateur radio is defined as a station located more than 50 kilometers above Earth's surface. That altitude threshold is the key — it doesn't need to be manned, and it's specifically defined in FCC Part 97."
    E["T1A08"] = "Frequency coordination for repeaters and auxiliary stations is handled by Volunteer Frequency Coordinators recognized by local amateurs. They're not appointed by the FCC or the ITU — it's a grassroots, self-governance system where the local amateur community manages shared resources."
    E["T1A09"] = "Frequency coordinators are selected by amateur operators in the local or regional area whose stations are eligible to be repeater or auxiliary stations. It's a bottom-up selection process by the amateur community, not a top-down appointment by the FCC."
    E["T1A10"] = "To be a control operator of a RACES station, you need both an FCC amateur license AND certification of current enrollment by a civil defense organization. Just having a license isn't enough — you must be specifically enrolled and certified by the civil defense agency that manages your local RACES program."
    E["T1A11"] = "Willful or malicious interference to any station is always prohibited under FCC rules. There are no circumstances where intentionally jamming or interfering with another station is allowed. International communications on VHF+ and third-party digital traffic are both perfectly fine."

    # ── T1B ──────────────────────────────────────────────────────────
    E["T1B01"] = "Technician licensees have phone privileges on 10 meters from 28.300 to 28.500 MHz, and that is their only HF phone segment. The segment from 28.000 to 28.300 is for CW and data, so 28.050 to 28.150 and 28.100 to 28.300 are not phone segments for Technicians. 28.500 to 28.600 is above the Technician limit. Above 50 MHz, Technicians have all amateur privileges. Phone is allowed in most of those bands, except the CW-only bottom 100 kilohertz of 6 and 2 meters and the data-only 219 to 220 megahertz segment."
    E["T1B02"] = "Any amateur with a Technician class or higher license can contact the ISS on VHF bands. You don't need a General or Extra license, and you don't need NASA approval. The ISS operates on 2 meters and 70 centimeters, which are fully available to Technicians."
    E["T1B03"] = "The 6 meter band runs from 50 to 54 MHz, and 52.525 MHz falls squarely inside it. It is the national FM simplex calling frequency on 6 meters. 49.00 MHz is just below the bottom of the band, so it is not amateur spectrum. 28.50 MHz is in the 10 meter band and 222.15 MHz is in the 1.25 meter band."
    E["T1B04"] = "146.52 MHz falls inside the 2 meter band, which runs from 144 to 148 MHz under 47 CFR 97.301(a). It is the national FM simplex calling frequency, so it is worth memorizing. The 6 meter band is 50 to 54 MHz, the 70 centimeter band is 420 to 450 MHz, and 20 meters is down around 14 MHz on HF, so none of those include 146.52."
    E["T1B05"] = "Technicians are authorized to use digital modes like FT8 on 10 meters, 6 meters, and 2 meters — all of these bands include frequencies where Technicians have data privileges. This makes all three answers correct."
    E["T1B06"] = "Technician class operators have HF phone privileges only on the 10-meter band (28.300–28.500 MHz). They have CW privileges on 80, 40, 15, and 10 meters, but voice/phone is limited to just 10 meters on HF."
    E["T1B07"] = "Under 47 CFR 97.305, the bottom 100 kilohertz of both the 6 meter band, 50.0 to 50.1 MHz, and the 2 meter band, 144.0 to 144.1 MHz, are limited to CW only. The other choices are not CW-only segments. 219 to 220 MHz is set aside for fixed digital message forwarding systems, and neither 420.0 to 420.1 MHz nor 902.0 to 902.1 MHz carries a CW-only restriction. That rules out All these choices are correct."
    E["T1B08"] = "Where amateur radio is a secondary service, other services hold the primary allocation, as the table in 47 CFR 97.303 shows. U.S. amateurs may find non-amateur stations there and must not cause them harmful interference. They also have to accept interference from them. Being secondary has nothing to do with giving foreign amateurs priority, and it does not ban international or digital communications in those segments."
    E["T1B09"] = "All three reasons are correct. The frequency display on your radio may be slightly off due to calibration error, and your transmitter can drift a little as it warms up. Even when the display is exactly right, your signal is not a single point. Its modulation sidebands extend some distance either side of the displayed frequency. The rules require your entire signal to stay inside the band, so leave a margin from any band or sub-band edge."
    E["T1B10"] = "Under 47 CFR 97.305(c), phone emissions, including SSB, are authorized in at least some segment of every amateur band above 50 MHz. That is why you hear weak-signal SSB on 6 meters, 2 meters, and 70 centimeters. SSB is not limited to repeaters, those VHF and UHF phone segments are not reserved for General class and higher, and there is no 25-watt rule that opens up any band to SSB."
    E["T1B11"] = "Under 47 CFR 97.313(c), Technicians may run up to 200 watts peak envelope power in their HF segments. Those are the CW segments on 80, 40, and 15 meters and the 10 meter segment from 28.0 to 28.5 MHz. 100 watts is a common trap because so many HF radios put out 100 watts, but the rule says 200. 50 and 10 watts are simply wrong."
    E["T1B12"] = "Above 30 MHz, Technicians have the same general power limit as every other license class: 1500 watts peak envelope power, under 47 CFR 97.313(b). The question says except for some specific restrictions because a few segments have lower limits. One example is 50 watts on 219 to 220 MHz. You should also always use the minimum power needed to communicate. 50, 100, and 500 watts are not the general limit."

    # ── T1C ──────────────────────────────────────────────────────────
    E["T1C01"] = "The FCC currently issues new licenses in only three classes: Technician, General, and Amateur Extra. Novice, Technician Plus, and Advanced licenses are no longer issued. Existing Novice and Advanced licenses can still be renewed. Under 47 CFR 97.21, a Technician Plus renewal is processed as a Technician license."
    E["T1C02"] = "Under 47 CFR 97.19, any licensed amateur may apply for a vanity call sign. Your license class only limits which call sign formats you can choose. Short formats such as one-by-two calls are reserved for Amateur Extra licensees. There is no requirement to hold a General or Extra license, and no requirement to have been licensed for 10 years before applying."
    E["T1C03"] = "Under 47 CFR 97.117, international communications by FCC-licensed amateur stations are limited to communications incidental to the purposes of the Amateur Radio Service and remarks of a personal character. Conducting business is not allowed. Contacts are not limited to contest exchanges either. Anything resembling an international broadcast station's programming is prohibited, because amateurs may not broadcast."
    E["T1C04"] = "47 CFR 97.23 requires every license applicant and licensee to give the FCC an email address and keep it current. If FCC correspondence is returned as undeliverable because you failed to provide a correct email address, the FCC may revoke your station license or suspend your operator license. The rule does not mention a fine or losing access to your license record, and the requirement definitely exists."
    E["T1C05"] = "KF1XXX follows the two-by-three format of a Group D call sign: a two-letter prefix, one numeral, and a three-letter suffix. That is the format new Technicians are normally issued. KA1X is a two-by-one format and W1XX is a one-by-two format. Both are Group A formats reserved for Amateur Extra licensees. A call sign doesn't reliably tell you someone's current license class, because vanity call signs and upgrades let people keep or choose other formats."
    E["T1C06"] = "You may operate your amateur radio from a US-documented vessel in international waters with the master's permission. You don't need special FCC authorization for maritime mobile operation — your regular amateur license covers it, as long as the vessel is US-documented and you have the captain's OK."
    E["T1C07"] = "You may request an amateur radio license renewal up to 90 days before the expiration date. Don't wait until the last minute — file your renewal well in advance to ensure there's no gap in your license."
    E["T1C08"] = "The normal term for an FCC-issued amateur radio license is ten years. After that, you need to renew. If your license expires, you have a two-year grace period to renew, but you cannot transmit during that grace period. No transmitting with an expired license."
    E["T1C09"] = "Under 47 CFR 97.21(b), if your license expires you have a two-year grace period to apply for renewal and keep your call sign. You may not transmit during that grace period until the license is renewed. Three, five, and ten years are wrong; ten years is the normal license term, not the grace period."
    E["T1C10"] = "For your first license, you may transmit as soon as your license grant appears in the FCC's license database, the Universal Licensing System. The CSCE from your exam session gives operating privileges only to someone who already holds a license and has just upgraded. A brand-new licensee must wait for the FCC grant. The ARRL website is not the official record, and the FCC no longer mails paper licenses, so don't wait for one."
    E["T1C11"] = "No. Under 47 CFR 97.21(b), you have a two-year grace period to renew an expired license, but you have no operating privileges during that time. You must wait until the renewal is granted before you transmit again. The grace period only protects your ability to renew and keep your call sign. Applying for renewal does not restore privileges either."

    # ── T1D ──────────────────────────────────────────────────────────
    E["T1D01"] = "Under 47 CFR 97.111(a)(1), FCC-licensed amateurs may communicate with amateurs in other countries except any country whose administration has notified the International Telecommunication Union, the ITU, that it objects to such communications. The ITU is the international treaty body for radio. The ARRL is a U.S. membership organization and the IARU is a federation of amateur radio societies, and neither one has authority to ban communications with a country."
    E["T1D02"] = "Broadcasting, meaning transmissions intended for reception by the general public, is prohibited for amateur stations under 47 CFR 97.113(b). Some one-way transmissions are specifically allowed under 47 CFR 97.111(b). These include Morse code practice, telecommand and telemetry, and information bulletins of direct interest to amateurs, such as announcements of upcoming ham radio operating events."
    E["T1D03"] = "Encoded or encrypted messages are only permitted when transmitting control commands to space stations or model craft. All other amateur communications must be transmitted in the clear — obscuring the meaning of your messages is prohibited because amateur radio is meant to be open and transparent."
    E["T1D04"] = "Music using a phone emission is prohibited under 47 CFR 97.113(a)(4). The one exception, in 97.113(c), is music that is incidental to an authorized retransmission of communications between a manned spacecraft and its Earth stations. Avoiding spurious emissions, keeping it under three minutes per hour, or transmitting above 1280 MHz does not make music legal."
    E["T1D05"] = "Under 47 CFR 97.113(a)(3)(ii), you may tell other amateurs about equipment for sale or trade if it is the kind of equipment normally used in an amateur station and you don't do it on a regular basis. That allows the occasional swap of your own gear but not running a business over the air. Selling at a profit is allowed, and the rule does not require that the equipment belong to someone other than you or your relatives."
    E["T1D06"] = "Transmitting obscene or indecent language on amateur frequencies is prohibited at all times. There's no exception based on time of day, power level, or frequency. The FCC's rules on this are absolute — no profanity on the air, period."
    E["T1D07"] = "An auxiliary station transmits point-to-point communications within a system of cooperating amateur stations, under 47 CFR 97.3(a)(7). The textbook example is a one-way link that carries signals from a remote repeater receiver back to the main repeater transmitter. A backup radio for your home station, a MARS network station, and a second station at a multi-operator contest are not auxiliary stations."
    E["T1D08"] = "An amateur station's control operator may receive compensation when the communication is part of classroom instruction at an educational institution. Teaching amateur radio as part of a school curriculum is the exception that allows compensated operation."
    E["T1D09"] = "Amateur stations may transmit information supporting broadcasting, program production, or news gathering only when no other means is available and it directly relates to the immediate safety of human life or protection of property. The emergency exception is the key."
    E["T1D10"] = "Under 47 CFR 97.3(a)(10), broadcasting means transmissions intended for reception by the general public, whether direct or relayed. That is why broadcasting is prohibited on amateur frequencies. Two-way contacts, ordinary transmissions by a licensed station, and messages directed only to other amateurs are all normal amateur communications, not broadcasting."
    E["T1D11"] = "Under 47 CFR 97.215, transmissions directed only to a model craft do not need on-the-air identification. Examples are radio-controlled airplanes, boats, and cars. Instead, a label showing the station call sign and the licensee's name and address must be attached to the transmitter, and power is limited to 1 watt. Short tune-up transmissions, unmodulated carriers, and very low power transmissions still require identification."
    E["T1D12"] = "When making on-the-air test transmissions, you must identify the transmitting station. Even if you're just testing your equipment or running diagnostics, you still need to send your call sign. No exceptions — if you're transmitting, you must identify."

    # ── T1E ──────────────────────────────────────────────────────────
    E["T1E01"] = "Never. Under 47 CFR 97.7, every amateur station must have a control operator whenever it is transmitting. A repeater or auxiliary station under automatic control still has a control operator; that person just doesn't have to be at the control point. When the licensee is away, the licensed amateur using the station is the control operator."
    E["T1E02"] = "Any amateur whose license class allows transmitting on the satellite's uplink frequency may be the control operator for satellite contacts. Most amateur satellites use VHF and UHF uplinks, so Technicians can use them. The FCC rules do not require an Extra class license, a satellite operator certification, or AMSAT membership."
    E["T1E03"] = "Under 47 CFR 97.103(b), the station licensee must designate the station control operator. You decide who may be the control operator of your station. The FCC does not assign control operators, a frequency coordinator only recommends repeater channels, and another licensed operator cannot simply appoint themselves at your station."
    E["T1E04"] = "A station's transmitting privileges are set by the class of operator license held by the control operator. A control operator may only use the privileges of their own license class. If a Technician is the control operator at an Extra's station, only Technician frequencies may be used. Amateur licenses do not list frequencies, coordinators only recommend repeater channels, and the highest license held by someone else in the room does not matter."
    E["T1E05"] = "Under 47 CFR 97.3(a)(14), the control point is the location at which the control operator function is performed. It is where the operator actually controls the station. For a station operated over the internet, that may be far from the transmitter. The control point is not defined by where the antenna or transmitter sits, and it has nothing to do with the licensee's mailing address."
    E["T1E06"] = "A Technician may never be the control operator of a station operating in an Amateur Extra Class band segment, except in an emergency. A control operator may only use the privileges of their own license class. Being designated by an Extra, joining a contest team, or using a club station with an Extra trustee does not change that. The emergency exception in 47 CFR 97.403 allows any means of communication when needed for the immediate safety of human life or protection of property and normal communication systems are not available."
    E["T1E07"] = "Under 47 CFR 97.103(a), the station licensee is always responsible for the proper operation of the station. When someone else is the control operator, the control operator and the station licensee are equally responsible. Neither person alone carries all the responsibility, and other licensed amateurs who simply happen to be present are not responsible."
    E["T1E08"] = "Repeater operation is the classic example of automatic control. Under 47 CFR 97.3(a)(6), automatic control means the station follows the FCC rules without the control operator being present at a control point, and 97.205(d) allows repeaters to be automatically controlled. Controlling a station over the internet is remote control. Using a computer to send CW or to identify automatically is just a station accessory, and the operator is still in control."
    E["T1E09"] = "Any amateur station may be remotely controlled. There's no restriction limiting remote control to only repeaters, digital stations, or automatically controlled stations. If you can maintain a control link, you can operate any station remotely."
    E["T1E10"] = "Operating the station over the internet is an example of remote control. Under 47 CFR 97.3(a)(39), remote control means the control operator indirectly manipulates the station's operating adjustments through a control link. A software defined radio by itself is just a type of radio, not remote control. Controlling a model aircraft, boat, or car is telecommand. Earth-Moon-Earth is a way of communicating by bouncing signals off the Moon."
    E["T1E11"] = "A control operator, as defined in Part 97, is an amateur operator designated by the licensee to be responsible for transmissions and FCC rules compliance at that station. It's about responsibility for rule compliance, not just about speaking into the microphone."

    # ── T1F ──────────────────────────────────────────────────────────
    E["T1F01"] = "Under 47 CFR 97.103(c), the station licensee must make the station and its records available for inspection at any time upon request by an FCC representative. The rules don't require ten days' notice, a written notice, or a warrant. Agreeing to inspection is a condition of holding the license."
    E["T1F02"] = "When using tactical call signs like \"Race Headquarters,\" you must still identify with your FCC-assigned call sign at least every 10 minutes during and at the end of a communication. Tactical calls are allowed for convenience, but your legal call sign is still required at regular intervals."
    E["T1F03"] = "Under 47 CFR 97.119(a), you must transmit your assigned call sign at least every 10 minutes during a communication and at the end of the communication. This applies to every mode, not just phone. You don't have to identify at the beginning of a contact or during every single transmission, and 15 minutes is too long."
    E["T1F04"] = "When using a phone emission, you must identify in English. Regardless of what language you're using for the conversation itself, your station identification must be in English. This ensures anyone monitoring can identify who's transmitting."
    E["T1F05"] = "Under 47 CFR 97.119(b), a station using phone may identify by sending its call sign using either a CW emission or a phone emission. Phone identification must be in English, and CW identification sent by an automatic ID keyer must be no faster than 20 words per minute. Phone-only identification is not required, and RPT and R are not required identification indicators for phone stations."
    E["T1F06"] = "Under 47 CFR 97.119(c), an indicator added to your call sign must be separated from it by a slant mark, or on phone by any suitable word that means slant mark. Stroke, slant, and slash are all acceptable, so all these choices are correct."
    E["T1F07"] = "When a non-licensed person speaks to a foreign station through your amateur station, the foreign station must be in a country with which the US has a third-party agreement. Not all countries allow third-party traffic — you must verify the agreement exists before allowing it."
    E["T1F08"] = "Third-party communications are defined as a message from a control operator (first party) of an amateur station to another amateur station's control operator (second party) on behalf of another person (the third party). The third party is the person whose message is being passed."
    E["T1F09"] = "A repeater is the type of amateur station that simultaneously retransmits the signal of another amateur station on a different channel. The key words are \"simultaneously\" and \"different channel\" — that's what distinguishes a repeater from other station types."
    E["T1F10"] = "Under 47 CFR 97.205(g), the control operator of a repeater that inadvertently retransmits communications violating the rules is not accountable for them. The control operator of the station that originated the transmission is accountable. The repeater simply passed along what it received. That rules out the repeater's control operator, its owner, and both together."
    E["T1F11"] = "To get a club station license, the club must have at least four members and a licensed trustee. The trustee is the person responsible for the club station's compliance with FCC rules. ARRL registration is not required, and club members don't all need to be licensed."

    # ── T2A ──────────────────────────────────────────────────────────
    E["T2A01"] = "On the 2-meter band, the standard repeater frequency offset is plus or minus 600 kHz. Your radio transmits 600 kHz above or below the repeater's output frequency. This is one of the most commonly tested facts on the Technician exam."
    E["T2A02"] = "The national FM simplex calling frequency on 2 meters is 146.520 MHz. This is arguably the most important frequency for a new Technician to memorize. Simplex means you transmit and receive on the same frequency — no repeater involved."
    E["T2A03"] = "On the 70-centimeter band, the standard repeater offset is plus or minus 5 MHz — much larger than the 600 kHz offset on 2 meters. The higher frequency band uses a larger offset."
    E["T2A04"] = "To call another station on a repeater when you know their call sign, say their call sign followed by your call sign. Don't use \"break, break\" (that's for emergencies), and don't call CQ on a repeater — just call them directly."
    E["T2A05"] = "When you answer a CQ, say the other station's call sign first and then your own. That tells them right away that you're answering their call and who you are. You don't send CQ back, because they're the one looking for a contact. Putting your call sign first, or opening with a signal report, makes it less clear who you're calling."
    E["T2A06"] = "To seek a call from any phone station without a repeater, you call CQ: repeat \"CQ\" a few times, say \"this is\" followed by your call sign, then pause and listen for a response. Repeat as necessary. This is the standard procedure for initiating contacts on simplex or HF."
    E["T2A07"] = "A repeater offset is the difference between a repeater's transmit and receive frequencies. You transmit on one frequency and the repeater retransmits on another. The offset is that gap between the two — typically 600 kHz on 2 meters or 5 MHz on 70 cm."
    E["T2A08"] = "CQ means \"calling any station\" — it's an open invitation for anyone to respond. If you hear someone call CQ, they want to have a contact with whoever answers. Despite various folk etymologies, CQ simply means \"I'm looking for a contact.\""
    E["T2A09"] = "To indicate you're listening on a repeater and available for a contact, say your call sign followed by the word \"listening.\" This is a quick, courteous way to let others know you're monitoring without making a formal CQ call."
    E["T2A10"] = "A band plan is a voluntary guideline for using different modes or activities within an amateur band. FCC rules set the overall privileges, and band plans go further by suggesting where CW, SSB, digital modes, FM simplex, repeaters and satellites should operate so they don't interfere with each other. Band plans are developed nationally and regionally, by groups such as the ARRL and frequency coordinators, not by a single club. They aren't schedules or lists of net frequencies."
    E["T2A11"] = "Simplex means transmitting and receiving on the same frequency, with stations taking turns. Full duplex means transmitting and receiving at the same time, usually on two different frequencies, the way a repeater or a telephone works. Diplex and multiplex are terms for combining several signals onto one path or system. They don't describe a station using a single frequency."

    # ── T2B ──────────────────────────────────────────────────────────
    E["T2B01"] = "The reverse function on a VHF/UHF transceiver swaps your transmit and receive frequencies, letting you listen on the repeater's input frequency. This is useful for checking if a station is close enough for direct simplex contact without using the repeater."
    E["T2B02"] = "CTCSS stands for Continuous Tone-Coded Squelch System. Your radio adds a low tone, roughly 67 to 254 hertz, under your voice, and the repeater's receiver opens its squelch only when it hears that tone. Carrier squelch opens on any signal at all, with no tone needed. A tone burst is a short audible tone sent at the start of a transmission. DTMF uses pairs of audible tones, like a telephone keypad."
    E["T2B03"] = "In a linked repeater network, a signal received by any one repeater is retransmitted by all the repeaters in the network. The links can be radio or internet connections, and they spread one conversation over a much wider area. A single repeater with several receivers is a receiver voting system, not a network. Having the same control operator doesn't link repeaters, and APRS is a position-reporting and data system, not the way voice repeaters are linked."
    E["T2B04"] = "All three can keep you out of a repeater you can hear. With the wrong offset, you're transmitting on a frequency the repeater isn't listening to. Many repeaters also require a specific CTCSS tone or DCS code before they'll respond, so a wrong or missing tone or code leaves the repeater's receiver muted. If you can hear the repeater but can't get in, check the offset, the tone and the code."
    E["T2B05"] = "If your FM transmission audio drops out on voice peaks, you're probably talking too loudly and over-deviating the signal. The fix is to back off from the microphone. Over-deviation causes the receiver to lose the signal at audio peaks."
    E["T2B06"] = "DTMF (Dual-Tone Multi-Frequency) uses two simultaneous audio tones to signal a repeater — one from a high-frequency group and one from a low-frequency group, just like touch-tone telephones. CTCSS uses a single sub-audible tone, which is different from DTMF's paired audible tones."
    E["T2B07"] = "To join a digital repeater's talkgroup, you program your radio with the group's ID or code. No registration with frequency coordinators, no club membership required, and no DTMF programming needed — just enter the correct talkgroup ID into your radio."
    E["T2B08"] = "When two stations on the same frequency interfere with each other, they should negotiate continued use of the frequency. Nobody \"owns\" a frequency in amateur radio — it's about cooperation. Neither station has preemptive rights; they work it out courteously."
    E["T2B09"] = "Simplex channels are set aside in VHF and UHF band plans so stations within range of each other can talk directly without tying up a repeater. That leaves the repeater free for stations that really need its wider coverage. Simplex channels aren't reserved for contests or for working DX. And simplex doesn't go through a repeater at all, so it has nothing to do with accessing one without an offset."
    E["T2B10"] = "QRM means you're receiving interference from other stations, which is man-made interference. One way to remember it is that the M stands for man-made. QRN is natural noise such as static from lightning, QTH is your location, and QSB means the signal is fading."
    E["T2B11"] = "QSY means changing frequency, as in \"let's QSY to 146.55.\" QRU means \"I have nothing for you.\" QSL means \"I acknowledge receipt.\" QRZ asks \"who is calling me?\" Only QSY is about moving to a new frequency."
    E["T2B12"] = "The DMR digital color code is an access code that must be programmed into your transmitter to access a specific DMR repeater. Think of it as the digital equivalent of a CTCSS tone — it ensures your radio only talks to the intended repeater and ignores others on the same frequency."
    E["T2B13"] = "Squelch mutes the receiver audio when no signal is present, so you don't hear constant hiss between transmissions. When a signal strong enough to cross the squelch threshold comes in, the audio opens. Key clicks are fixed by shaping the CW keying, parasitic oscillations are an amplifier problem, and impulse noise is handled by a noise blanker. None of those is what squelch does."
    E["T2B14"] = "A talkgroup is an identifier used by DMR (Digital Mobile Radio) to organize radio traffic so that those who want to hear a particular group aren't bothered by other radio traffic on the same repeater. It's like a virtual channel within a DMR system — only radios programmed for that talkgroup hear the conversation."

    # ── T2C ──────────────────────────────────────────────────────────
    E["T2C01"] = "FCC Part 97 rules ALWAYS apply to amateur station operation. There is no exception — not during RACES, not under FEMA rules, not under ARES rules. However, in genuine emergencies involving immediate safety of life or property, operators may deviate from normal frequency restrictions."
    E["T2C02"] = "The typical job of a Net Control Station is to call the net to order and direct communications between the stations checking in. The NCS decides who transmits and when, so the net runs in an orderly way. The net's regular time and frequency are normally set ahead of time by the net's organizers. And every control operator is responsible for staying within their own license privileges, so verifying licenses isn't a typical NCS duty."
    E["T2C03"] = "To ensure voice messages with unusual words are received correctly, spell them out using a standard phonetic alphabet — Alpha, Bravo, Charlie. Don't yell louder (that causes distortion), and Q-codes aren't used for this purpose."
    E["T2C04"] = "RACES (Radio Amateur Civil Emergency Service) is an FCC Part 97 amateur radio service for civil defense communications during national emergencies. It's defined in the FCC rules and is specifically for civil defense purposes, separate from ARES."
    E["T2C05"] = "In net operation, \"traffic\" refers to formal messages exchanged by net stations. Like traffic on a road means vehicles moving, traffic on a net means messages being passed and relayed between stations."
    E["T2C06"] = "ARES (Amateur Radio Emergency Service) is a group of licensed amateurs who have voluntarily registered their qualifications and equipment for public service communications. It's volunteer-based — not a military organization, and separate from RACES."
    E["T2C07"] = "The standard practice in a net is to transmit only when the net control station directs you to, unless you're reporting an emergency. That keeps the net orderly and lets the NCS manage the traffic. When you check in, you give your call sign and usually your name, not your mailing address from the FCC database. There's also no requirement to record the time of each transmission."
    E["T2C08"] = "Winlink is the system that relays messages using email addresses based on amateur call signs. It bridges amateur radio and email, allowing messages to flow between radio operators and internet email users. FT8, PSK31, and AMTOR are digital modes, not email relay systems."
    E["T2C09"] = "Yes, but only in situations involving the immediate safety of human life or the immediate protection of property, when normal communication systems aren't available. In that case, FCC Part 97 lets an amateur station use any means of radio communication at its disposal. Being part of a FEMA or RACES plan doesn't by itself give you extra frequency privileges. RACES operators still operate within the privileges of their own license class."
    E["T2C10"] = "The preamble of a formal traffic message holds the information needed to track the message. That includes the message number, precedence, handling instructions, station of origin, check, place of origin, time filed and date. The recipient's name, address and telephone number go in the address section, not the preamble. The originating station's email address isn't part of the preamble either."
    E["T2C11"] = "The check is the number of words or word equivalents in the text of the message. The receiving station counts the words it copied and compares that number to the check, so a mismatch shows that something was missed. The originating station's call sign goes in a separate preamble field called the station of origin. Notes about who the message was received from and sent to are recorded elsewhere on the form, not in the check."
    E["T2C12"] = "RACES (Radio Amateur Civil Emergency Service) requires certification by a civil defense agency. To participate in RACES, you must be enrolled and certified by your local civil defense organization. ARES is a volunteer group run by the ARRL, SKYWARN is the National Weather Service's storm-spotter program, and MARS is a military auxiliary program run by the Department of Defense, so none of them requires civil defense certification."

    # ── T3A ──────────────────────────────────────────────────────────
    E["T3A01"] = "VHF signals vary greatly when the antenna moves just a few feet because of multipath propagation. Your signal bounces off buildings, hills, and other objects, creating multiple copies that either cancel (destructive interference) or reinforce (constructive interference). At 2-meter wavelengths, a move of just a few feet can shift you from a deep null to a strong peak."
    E["T3A02"] = "Vegetation absorbs UHF and microwave signals. The water content in leaves is particularly effective at soaking up these higher frequencies, leading to poor reception of weak signals in wooded areas. This is a real-world effect any VHF/UHF operator notices."
    E["T3A03"] = "Horizontal polarization is the normal choice for long-distance CW and SSB contacts on VHF and UHF, which is often called weak-signal work. Stations at both ends need to match, and the convention is horizontal antennas, usually Yagis. Vertical polarization is the standard for FM, repeaters and mobile operation, so a vertical antenna would suffer a big cross-polarization loss with horizontal weak-signal stations. Circular polarization is used mainly for satellite work."
    E["T3A04"] = "When antennas at opposite ends of a VHF or UHF link are cross-polarized (one vertical, one horizontal), the received signal strength drops significantly — potentially by 20 dB or more. Both stations should use the same polarization. Cross-polarization doesn't invert sidebands or create echoes; it just weakens the signal."
    E["T3A05"] = "If buildings or other obstructions block the direct path, aim your directional antenna to find a path that reflects your signal to the repeater, for example off a large building or a hillside. Switching to horizontal polarization doesn't get you around the obstruction, and it would mismatch the repeater's vertical antenna. The \"long path\" is an HF idea, where signals go the long way around the Earth. Raising your SWR only wastes power."
    E["T3A06"] = "\"Picket fencing\" is the rapid flutter you hear on mobile VHF and UHF signals. As a vehicle moves, it passes through alternating nulls and peaks created by multipath propagation. The signal rapidly cuts in and out, sounding like someone talking from behind a picket fence."
    E["T3A07"] = "Precipitation such as rain, snow and fog can decrease range at microwave frequencies. Water droplets absorb and scatter microwave energy, and the effect gets stronger as frequency goes up. High winds, low barometric pressure and cold temperatures have no significant direct effect on how far microwave signals travel."
    E["T3A08"] = "Irregular fading of ionospheric signals is caused by the random combining of signals that arrive by different paths. The paths through the ionosphere keep changing, so the copies of the signal reinforce and cancel each other unpredictably. Faraday rotation changes a signal's polarization, not its frequency. Thunderstorms cause static crashes, not fading, and intermodulation distortion is an equipment problem."
    E["T3A09"] = "Because the ionosphere changes polarization randomly, a signal that comes back from it is elliptically polarized, with parts in both the horizontal and vertical planes. That means either a vertically or a horizontally polarized antenna can be used for sending or receiving on ionospheric paths. So the two stations don't need matching polarization, the way they do on a line-of-sight VHF path. Digital modes and FM voice still work fine."
    E["T3A10"] = "Multipath makes data error rates likely to increase. Copies of the signal arrive at slightly different times and smear into each other, so the receiver has trouble telling one data symbol from the next. Changing the data rate by a factor equal to the number of paths isn't how it works. Using FM doesn't make a signal immune to multipath either."
    E["T3A11"] = "The ionosphere can reflect HF radio waves, enabling long-distance communication. This region of the atmosphere, ionized by solar radiation, acts as a mirror for certain frequencies. VHF signals generally pass through the ionosphere, which is why HF is used for long-distance skywave propagation."
    E["T3A12"] = "Fog and rain have very little effect on 10-meter and 6-meter band signals. The wavelengths at these frequencies are long enough that weather just doesn't matter. Rain fade becomes significant only at microwave frequencies, typically above 10 GHz."

    # ── T3B ──────────────────────────────────────────────────────────
    E["T3B01"] = "Radio waves in free space are made up of mutually perpendicular electric and magnetic fields — this is what we call an electromagnetic wave. The electric and magnetic components are always at right angles to each other and to the direction of travel."
    E["T3B02"] = "A radio wave's polarization is defined by the orientation of its electric field. A vertical antenna produces a vertical electric field, so its signal is vertically polarized. The magnetic field is always at right angles to the electric field, but by convention it's the electric field that names the polarization. Energy ratios and the ratio of velocity to wavelength have nothing to do with polarization."
    E["T3B03"] = "A radio wave has two components, an electric field and a magnetic field, which travel together at right angles to each other. Voltage and current exist in the antenna and feed line, but in space the wave is made of fields. Impedance and reactance are properties of circuits. Ionizing and non-ionizing are categories of radiation, and radio waves are non-ionizing, so they aren't the components of a wave."
    E["T3B04"] = "Radio waves travel through free space at the speed of light — approximately 300,000,000 meters per second. This is a fundamental constant of physics. All electromagnetic radiation — radio waves, light, X-rays — travels at this speed in a vacuum."
    E["T3B05"] = "Wavelength and frequency have an inverse relationship — as one goes up, the other goes down. They're linked by the speed of light: wavelength × frequency = speed of light. This means higher frequency = shorter wavelength, and lower frequency = longer wavelength."
    E["T3B06"] = "The formula for converting frequency to approximate wavelength in meters is: wavelength = 300 / frequency in MHz. So 146 MHz ≈ 2 meters. This simple formula is essential for the exam and for practical antenna work."
    E["T3B07"] = "Besides frequency, amateur bands are identified by their approximate wavelength in meters, like 2 meters or 70 centimeters. You can get the wavelength by dividing 300 by the frequency in megahertz. Amateur bands aren't usually named with channel numbers the way CB is, or with letter designators."
    E["T3B08"] = "VHF, or very high frequency, runs from 30 to 300 megahertz. It includes the 6-meter, 2-meter and 1.25-meter amateur bands. 30 to 300 kilohertz is low frequency, 300 to 3000 kilohertz is medium frequency, and 300 to 3000 megahertz is UHF."
    E["T3B09"] = "UHF is defined as frequencies from 300 to 3000 MHz. The amateur 70-centimeter band (420–450 MHz) falls in the UHF range. VHF is 30–300 MHz, SHF is 3–30 GHz, and EHF is 30–300 GHz."
    E["T3B10"] = "HF, or high frequency, runs from 3 to 30 megahertz, from the 80-meter band up through 10 meters. 300 to 3000 kilohertz is the medium frequency range, which includes AM broadcast and the 160-meter band. 30 to 300 megahertz is VHF, and 300 to 3000 megahertz is UHF."
    E["T3B11"] = "The approximate velocity of radio waves in free space is 300,000,000 meters per second — the speed of light. This is a universal constant for all electromagnetic radiation, whether it's radio waves, visible light, or X-rays."
    E["T3B12"] = "All radio frequencies travel at the same velocity in free space — the speed of light (approximately 300,000,000 meters per second). Whether it's 1 MHz or 10 GHz, all electromagnetic waves travel at the same speed in a vacuum. Frequency affects wavelength but not speed."

    # ── T3C ──────────────────────────────────────────────────────────
    E["T3C01"] = "Simplex UHF signals are rarely heard beyond the radio horizon because the ionosphere usually doesn't propagate them. UHF frequencies are too high to be bent back to Earth, so they pass through into space. It isn't that the signals are too weak, and there's no FCC rule that limits their distance. The D region mostly absorbs lower HF and medium frequencies, not UHF."
    E["T3C02"] = "Compared with VHF and higher frequencies, long-distance ionospheric propagation is far more common on HF. The ionosphere regularly bends HF signals back to Earth, allowing contacts over thousands of miles. HF antennas are generally larger, not smaller, because the wavelengths are longer. The VHF and UHF bands have more room for wide signals, and HF has more static, not less."
    E["T3C03"] = "VHF signals received via auroral backscatter are distorted, with a characteristic raspy sound. The aurora creates an irregular, constantly moving reflective surface that scatters and distorts signals. Voices sound rough and garbled, though CW often gets through better than voice."
    E["T3C04"] = "Sporadic E propagation is most commonly associated with occasional strong signals on the 10-, 6-, and 2-meter bands from beyond the radio horizon. Sporadic E creates intense but unpredictable patches of ionization in the E layer that can reflect VHF signals over hundreds of miles."
    E["T3C05"] = "Knife-edge diffraction lets radio signals bend around a sharp edge, such as a mountain ridge or the edge of a building, and reach stations behind the obstruction. Faraday rotation is a change of polarization in the ionosphere. Quantum tunneling is a subatomic effect. Doppler shift is a change in frequency caused by motion. None of those carry signals past an obstruction."
    E["T3C06"] = "Tropospheric ducting regularly allows over-the-horizon VHF and UHF contacts out to about 300 miles. A temperature inversion forms a duct in the lower atmosphere that guides signals far beyond the normal radio horizon. The D region doesn't refract VHF back to Earth; it mainly absorbs lower HF and medium-frequency signals, and VHF passes through it. F2 region refraction rarely supports anything above 6 meters. Faraday rotation is a polarization effect, not a way to extend range."
    E["T3C07"] = "Six meters is the best band for meteor scatter. The ionized trails that meteors leave in the upper atmosphere reflect signals around 50 megahertz well. On higher bands such as 2 meters, 70 centimeters and 33 centimeters, the reflections are weaker and much shorter, so contacts get harder and harder."
    E["T3C08"] = "Tropospheric ducting is caused by temperature inversions, where a layer of warm air sits above cooler air. The sharp change bends VHF and UHF signals back down, trapping them in a duct that can carry them hundreds of miles. Lightning causes static, and sunspots and solar flares affect the ionosphere, not the lower atmosphere. Storm updrafts don't create ducts."
    E["T3C09"] = "The best time for long-distance 10-meter propagation via the F region is from dawn to shortly after sunset during periods of high sunspot activity. Ten meters needs strong F-region ionization, and you get that only when sunlight is on the path and the sunspot cycle is near its peak. After dark the F region weakens, and during low sunspot activity 10 meters is usually closed for F-region skip even in daytime."
    E["T3C10"] = "Near the peak of the sunspot cycle, the F region can become ionized enough to refract signals on the 10-meter band and sometimes the 6-meter band, giving worldwide contacts. The 1.25-meter, 70-centimeter and 23-centimeter bands are much higher in frequency, and they pass through the ionosphere even at solar maximum."
    E["T3C11"] = "The radio horizon for VHF and UHF is more distant than the visual horizon because the atmosphere refracts radio waves slightly. The air gets thinner with height, which bends the waves gently downward so they follow the Earth's curve a bit farther. Radio waves don't travel faster than light, and dust particles have nothing to do with it."

    # ── T4A ──────────────────────────────────────────────────────────
    E["T4A01"] = "A typical 50-watt output mobile FM transceiver needs a power supply rated for at least 13.8 VDC at 12 amps or more. At 50 watts of RF output, the radio draws several amps from the DC supply. Using a supply with too low a current rating can cause voltage drops and unreliable operation."
    E["T4A02"] = "When selecting an SWR meter, consider both the frequency and the power level at which you'll make measurements. The meter must be designed for your frequency range, since one built for HF won't necessarily read accurately at VHF or UHF. It also must be rated for the power you'll run through it. Where it sits in the feed line and the highest SWR you expect aren't the deciding factors, and no meter can fix a poor antenna match."
    E["T4A03"] = "Short, heavy-gauge wires minimize voltage drop between the power supply and the transceiver. Long or thin wires have higher resistance, causing voltage to drop under load, which can make the radio malfunction or reduce output power. Keep the power cables short and thick."
    E["T4A04"] = "For FT8 operation, the transceiver's audio input and output are connected to the audio output and input of a computer running FT8 software (like WSJT-X). The computer generates and decodes the FT8 signals through the audio interface. Modern setups often use a USB audio interface built into the radio."
    E["T4A05"] = "An RF power meter goes in the feed line, between the transmitter and the antenna, because that's where the RF power flows. The power supply output and the power cable carry only DC, so a meter there can't measure RF output. Connecting it in parallel with the push-to-talk line and the antenna doesn't put it in the RF path at all."
    E["T4A06"] = "A computer-radio interface for digital modes carries three signals: receive audio from the radio to the computer, transmit audio from the computer to the radio, and transmitter keying to switch the radio into transmit. Many modern radios send all three over a single USB cable. The antenna and RF power don't go through the interface. GPS location data, DC power, and status or location information aren't the required signals."
    E["T4A07"] = "One connection a digital mode setup needs is from the computer's line in to the transceiver's speaker or audio output connector. That's how received audio gets into the computer so the software can decode it. The computer's line out feeds the transceiver's microphone or data input, not its speaker, and push-to-talk is a keying signal, not an audio line. Many modern radios handle these connections through a single USB cable."
    E["T4A08"] = "Flat copper strap is the preferred conductor for RF bonding because its wide, flat shape gives it low inductance, and so low impedance, at radio frequencies. Copper-clad steel wire and twisted-pair cable are thin round conductors with much higher inductance. Copper braid removed from coaxial cable is a poor choice because its strands corrode where they touch, which raises its resistance, especially outdoors."
    E["T4A09"] = "To estimate how long a battery will last, divide its ampere-hour rating by the equipment's average current draw. For example, a 20 amp-hour battery running a radio that averages 2 amps lasts about 10 hours. Use the average current, not the peak, because a radio draws heavy current only while transmitting. The other choices multiply or square things in ways that don't give you time."
    E["T4A10"] = "A digital mode hotspot provides nearby transceivers with communication access to a digital voice or data network. It acts as a personal low-power gateway, connecting your DMR, D-STAR, or Fusion radio to the internet-linked digital network through your home internet connection."
    E["T4A11"] = "The negative power return of a mobile transceiver should be connected at the 12-volt battery chassis ground — the same point where the battery's negative terminal connects to the vehicle chassis. This ensures a clean, low-resistance ground connection and prevents ground loops."
    E["T4A12"] = "An electronic keyer is a device that assists in manual sending of Morse code. It automatically generates properly timed dots and dashes when you press a paddle — you control the characters, but the keyer handles the precise timing. This makes CW sending faster, more consistent, and less tiring than using a straight key."

    # ── T4B ──────────────────────────────────────────────────────────
    E["T4B01"] = "Excessive microphone gain on SSB transmissions causes distorted audio and excessive bandwidth, potentially causing splatter into adjacent frequencies. The signal becomes over-modulated, and other stations will hear garbled, distorted audio. Keep the mic gain set properly — more is not better."
    E["T4B02"] = "You enter a transceiver's operating frequency with the keypad, by typing it in directly, or with the VFO knob, by tuning to it. CTCSS and DTMF encoders generate tones for accessing repeaters and sending control signals. Automatic Frequency Control keeps a receiver locked onto a signal that drifts slightly. Neither one sets the frequency you want."
    E["T4B03"] = "To hear a weak FM signal, set the squelch threshold so the receiver audio is on all the time, which means opening the squelch fully. You'll hear background noise, but weak signals won't be cut off by the squelch. Turning up the volume doesn't change the squelch threshold. Anti-squelch and squelch enhancement aren't real radio controls."
    E["T4B04"] = "When an FM signal is received slightly off frequency, the audio becomes distorted. FM receivers are designed for signals at the exact center frequency — even a small offset causes the discriminator to produce distorted audio. This is why accurate frequency setting matters for FM."
    E["T4B05"] = "The scanning function on an FM transceiver automatically tunes through a set of programmed frequencies (or across a band segment), pausing when it detects a signal. It's like a radio version of channel surfing — the radio searches for activity so you don't have to manually check each frequency."
    E["T4B06"] = "If an SSB voice sounds too high or too low in pitch, adjust the RIT, which stands for receiver incremental tuning and is also called the clarifier. It shifts your receive frequency slightly without moving your transmit frequency, so the voice sounds natural again. AGC and limiters control signal level, not pitch. Bandwidth selection changes the filter width, and tone squelch is an FM feature."
    E["T4B07"] = "A DMR code plug is configuration data loaded onto your radio to access repeaters and talkgroups. It contains the frequencies, color codes, talkgroup IDs, and other settings needed to use DMR repeaters in your area. Think of it as a programming profile for your digital radio."
    E["T4B08"] = "Having a choice of receiver filter bandwidths lets you select the best filter for the mode you're operating. A narrow filter for CW rejects adjacent signals, while a wider filter passes the full bandwidth of an SSB or FM signal. The right filter improves readability and reduces interference."
    E["T4B09"] = "On a DMR digital voice transceiver, you select a specific group of stations by choosing the appropriate talkgroup. Talkgroups are programmed into the radio via the code plug, and selecting one determines which group of users you hear and can talk to."
    E["T4B10"] = "A 2400 hertz filter gives the best signal-to-noise ratio for SSB reception because it matches the bandwidth of an SSB voice signal. It passes the voice but keeps out extra noise. 500 and 1000 hertz filters are too narrow for voice and are meant for CW. A 5000 hertz filter is wider than needed, so it lets in more noise and nearby interference."
    E["T4B11"] = "Before you transmit on a D-STAR transceiver, you must program in your call sign. D-STAR sends your call sign in its digital data stream for identification and for routing through repeaters and networks. Output power is an ordinary setting with a default value, and D-STAR uses a single built-in voice codec, so there's no codec type to choose."

    # ── T5A ──────────────────────────────────────────────────────────
    E["T5A01"] = "Electrical current is measured in amperes (amps). One ampere equals one coulomb of charge flowing past a point per second. The symbol for current is I, and the instrument that measures it is an ammeter."
    E["T5A02"] = "Electrical power is measured in watts, which tell you how fast electrical energy is being used. Volts measure electrical pressure, and amperes measure current. Watt-hours are the tempting wrong answer: they measure energy, which is power multiplied by time, not power itself."
    E["T5A03"] = "The flow of electrons in an electric circuit is called current. Current is what moves through wires and components, doing useful work. It's measured in amperes and represented by the letter I in equations."
    E["T5A04"] = "Frequency describes the number of times per second that an alternating current makes a complete cycle. One complete cycle per second equals one hertz (Hz). AC power in the US cycles at 60 Hz — meaning 60 complete cycles per second."
    E["T5A05"] = "A difference in electrical potential (voltage) causes electrons to flow. When there's a voltage difference between two points, electrons are pushed from the negative terminal toward the positive terminal. No voltage difference, no current flow."
    E["T5A06"] = "The unit of frequency is the hertz (Hz). One hertz equals one cycle per second. The unit is named after Heinrich Hertz, who first proved the existence of radio waves. The henry is the unit of inductance, the farad is the unit of capacitance, and epicycles per second is not a real unit."
    E["T5A07"] = "Metals are good conductors because they have many free electrons that can move easily from atom to atom. These loosely bound electrons in the outer shells of metal atoms create a \"sea\" of mobile charge carriers. Materials with tightly bound electrons (like glass or rubber) are insulators."
    E["T5A08"] = "Glass is a good electrical insulator — it strongly resists the flow of electric current because its electrons are tightly bound to their atoms. Sea water, stainless steel, and graphite all conduct electricity to varying degrees."
    E["T5A09"] = "Alternating current reverses direction, swinging back and forth between positive and negative directions, like the 60 hertz power from a wall outlet. Current that only goes between a positive direction and zero, or between a negative direction and zero, never reverses, so it is pulsating direct current, not AC. Because those two choices are wrong, all these answers are correct is wrong too."
    E["T5A10"] = "Power is the rate at which electrical energy is used, and it's measured in watts. A 100 watt bulb uses energy twice as fast as a 50 watt bulb. Resistance opposes current, current is the flow of electrons, and voltage is the pressure that pushes them, but none of those is a rate of energy use."
    E["T5A11"] = "Resistance opposes every kind of current flow: direct current, alternating current, and radio frequency current. A resistor turns some of the current's energy into heat no matter which way the current flows or how fast it alternates. Since each of the first three choices is correct, the answer is all these choices are correct."

    # ── T5B ──────────────────────────────────────────────────────────
    E["T5B01"] = "1.5 amperes equals 1,500 milliamperes. The prefix \"milli\" means one-thousandth, so to convert amps to milliamps, multiply by 1,000. Going the other way, divide milliamps by 1,000 to get amps."
    E["T5B02"] = "Kilo means one thousand, so divide 1,500,000 hertz by 1000 to get 1500 kilohertz, which is also 1.5 megahertz. 1500 megahertz is one thousand times too large, and 15 gigahertz is larger still. 150 kilohertz is ten times too small."
    E["T5B03"] = "The prefix kilo means one thousand, so one kilovolt is one thousand volts. One one-thousandth of a volt is a millivolt, and one million volts is a megavolt. One hundred volts simply isn't what kilo means."
    E["T5B04"] = "The prefix micro means one millionth, so one microvolt is one one-millionth of a volt. That's the size of the weak signals that arrive at a receiver's antenna input. One one-thousandth of a volt is a millivolt, and one million volts and one thousand kilovolts are both a megavolt, the opposite end of the scale."
    E["T5B05"] = "500 milliwatts equals 0.5 watts. \"Milli\" means one-thousandth, so 500 milliwatts = 500/1000 = 0.5 watts. Easy conversion — just move the decimal point three places."
    E["T5B06"] = "Milli means one-thousandth, so divide milliamperes by 1000 to get amperes: 3000 milliamperes divided by 1000 is 3 amperes. 0.003 amperes and 0.3 amperes are far too small. 3,000,000 amperes comes from multiplying by 1000 instead of dividing."
    E["T5B07"] = "Mega is one thousand times kilo, so to go from megahertz to kilohertz, multiply by 1000: 3.525 megahertz times 1000 is 3525 kilohertz. That frequency is in the 80 meter band. 0.003525 kilohertz and 35.25 kilohertz are much too small, and 3,525,000 kilohertz is one thousand times too large."
    E["T5B08"] = "Pico means one trillionth and micro means one millionth, so there are one million picofarads in one microfarad. That makes 1,000,000 picofarads exactly 1 microfarad. 0.001 microfarads is only 1000 picofarads, and the two larger choices are far too big."
    E["T5B09"] = "Doubling power is an increase of about 3 decibels. Going from 5 watts to 10 watts doubles the power, so the answer is 3 dB. The exact value is 10 times the logarithm of 2, which is 3.01 dB. A 10 dB increase would mean ten times the power, all the way to 50 watts."
    E["T5B10"] = "Cutting power in half is a change of minus 3 decibels. Going from 12 watts to 6 watts is one halving, minus 3 dB, and going from 6 watts to 3 watts is another, for a total of minus 6 dB. Minus 3 dB would stop at 6 watts, and minus 9 dB would take you all the way down to 1.5 watts."
    E["T5B11"] = "Multiplying power by ten is an increase of 10 decibels. 200 watts is exactly ten times 20 watts, so the increase is 10 dB. The other choices are too large: even 12 dB would be about 16 times the power."
    E["T5B12"] = "To convert kilohertz to megahertz, divide by 1000: 28,400 kilohertz divided by 1000 is 28.400 megahertz, in the 10 meter band. 28.400 kilohertz shrinks the number without changing to the larger unit, so it's one thousand times too small. 2.800 megahertz is about ten times too small, and 284.00 megahertz is ten times too large."
    E["T5B13"] = "2425 MHz equals 2.425 GHz. To convert MHz to GHz, divide by 1,000. This frequency is near the 2.4 GHz Wi-Fi band and falls within the amateur 13-centimeter band."

    # ── T5C ──────────────────────────────────────────────────────────
    E["T5C01"] = "Capacitance describes the ability to store energy in an electric field. A capacitor stores charge on its plates, and the amount of charge it can store per volt is its capacitance. Don't confuse this with inductance (energy in a magnetic field)."
    E["T5C02"] = "The unit of capacitance is the farad (F). Named after Michael Faraday, most practical capacitors are measured in microfarads (µF) or picofarads (pF), since one farad is an enormous amount of capacitance."
    E["T5C03"] = "Inductance describes the ability to store energy in a magnetic field. An inductor (coil) creates a magnetic field when current flows through it, and that field stores energy. Inductance opposes changes in current."
    E["T5C04"] = "The unit of inductance is the henry (H). Named after Joseph Henry, inductors are typically measured in millihenrys (mH) or microhenrys (µH). One henry is a lot of inductance — most practical inductors are much smaller."
    E["T5C05"] = "The unit of impedance is the ohm (Ω) — the same unit used for pure resistance. Impedance combines resistance and reactance (from capacitors and inductors) into a single measure of opposition to current flow in AC circuits."
    E["T5C06"] = "The abbreviation for kilohertz is kHz — lowercase k, uppercase H, lowercase z. The lowercase k indicates the metric prefix \"kilo\" (1,000), while Hz is the unit abbreviation for hertz. KHz, khz, and KHZ are all incorrect."
    E["T5C07"] = "The abbreviation for megahertz is MHz — uppercase M, uppercase H, lowercase z. The uppercase M indicates the metric prefix \"mega\" (1,000,000). Be careful: mHz (lowercase m) would mean millihertz, which is a completely different order of magnitude."
    E["T5C08"] = "The formula for electrical power in a DC circuit is P = I × E (power equals current times voltage). This is the most basic power formula. From this, you can derive P = I²R and P = E²/R using Ohm's Law substitutions."
    E["T5C09"] = "Power equals current times voltage. 10 amperes times 13.8 volts is 138 watts. The wrong choices come from adding, subtracting, or dividing instead of multiplying: 13.8 plus 10 is 23.8, 13.8 minus 10 is 3.8, and 10 divided by 13.8 is about 0.7."
    E["T5C10"] = "Power equals current times voltage: 2.5 amperes times 12 volts is 30 watts. The other choices come from dividing or adding instead. 12 divided by 2.5 is 4.8, 12 plus 2.5 is 14.5, and 2.5 divided by 12 is about 0.208."
    E["T5C11"] = "Rearrange the power formula so that current equals power divided by voltage. 120 watts divided by 12 volts is 10 amperes. 0.1 amperes comes from dividing the wrong way, 12 by 120, and 132 amperes comes from adding the two numbers."
    E["T5C12"] = "Impedance is the opposition to AC current flow, combining both resistance and reactance. Resistance opposes both AC and DC, while the reactance of capacitors and inductors depends on frequency, so impedance describes the total opposition in an AC circuit. It's measured in ohms, just like resistance. It is not the inverse of resistance or reactance, and it has nothing to do with power handling."

    # ── T5D ──────────────────────────────────────────────────────────
    E["T5D01"] = "The formula for current is I = E / R (current equals voltage divided by resistance). This is Ohm's Law rearranged to solve for current. If you know the voltage across a circuit and its resistance, you can calculate how much current flows."
    E["T5D02"] = "The formula for voltage is E = I × R (voltage equals current times resistance). This is the fundamental form of Ohm's Law. If 2 amps flow through 50 ohms, the voltage is 100 volts."
    E["T5D03"] = "The formula for resistance is R = E / I (resistance equals voltage divided by current). This is Ohm's Law solved for resistance. If you apply 12 volts and measure 3 amps, the resistance is 4 ohms."
    E["T5D04"] = "Using R = E / I: 90 volts ÷ 3 amps = 30 ohms. Ohm's Law makes this straightforward — divide the voltage by the current to find the resistance. Always make sure your units are consistent (volts, amps, ohms)."
    E["T5D05"] = "Resistance equals voltage divided by current. 12 volts divided by 1.5 amperes is 8 ohms. Multiplying gives 18, dividing the wrong way gives 0.125, and adding gives 13.5, and all of those are wrong."
    E["T5D06"] = "Resistance equals voltage divided by current: 12 volts divided by 4 amperes is 3 ohms. Multiplying gives 48 and adding gives 16, which are both wrong. 8 ohms is what you'd get by subtracting."
    E["T5D07"] = "Using I = E / R: 120 volts ÷ 80 ohms = 1.5 amps. Divide the voltage by the resistance to find the current. This is a common household example — 120V through a moderate resistance."
    E["T5D08"] = "Current equals voltage divided by resistance: 200 volts divided by 100 ohms is 2 amperes. Dividing the wrong way, 100 by 200, gives 0.5 amperes. Multiplying gives 20,000 amperes."
    E["T5D09"] = "Using I = E / R: 240 volts ÷ 24 ohms = 10 amps. Divide the voltage by the resistance. 240V is a common higher-voltage household circuit (used for dryers, ovens, etc.)."
    E["T5D10"] = "Voltage equals current times resistance: 0.5 amperes times 2 ohms is 1 volt. 0.25 volts comes from dividing 0.5 by 2, 2.5 volts comes from adding the numbers, and 1.5 volts comes from subtracting them."
    E["T5D11"] = "Voltage equals current times resistance: 1 ampere times 10 ohms is 10 volts. Adding the numbers gives 11 volts and subtracting gives 9 volts, and neither is how Ohm's law works."
    E["T5D12"] = "Voltage equals current times resistance: 2 amperes times 10 ohms is 20 volts. Dividing 2 by 10 gives 0.2 volts, adding gives 12 volts, and subtracting gives 8 volts, and all of those are wrong."
    E["T5D13"] = "In a series circuit, the current is always the same through all components. There's only one path for current to flow, so the same current passes through every component. Voltage divides among the components, but current is identical everywhere."
    E["T5D14"] = "In a parallel circuit, the voltage is always the same across all components. Each component connects directly across the power source, so they all see the same voltage. Current divides among the branches, but voltage is identical across all of them."

    # ── T6A ──────────────────────────────────────────────────────────
    E["T6A01"] = "A resistor opposes the flow of current in a circuit. Resistance is measured in ohms, and resistors are used to control current levels, divide voltages, and set operating points in circuits. They convert electrical energy to heat."
    E["T6A02"] = "A potentiometer is a variable resistor with a knob or slider, which makes it the classic volume control. Turning it changes how much of the audio signal is passed along to the amplifier. Fixed resistors and power resistors can't be adjusted, and a transformer changes AC voltage levels rather than offering a smooth adjustable control."
    E["T6A03"] = "A potentiometer is an adjustable resistor, so the electrical parameter it controls is resistance. Moving its wiper along the resistive element changes the resistance between the wiper and each end. Inductance and capacitance are adjusted with variable inductors and variable capacitors, and a potentiometer doesn't control field strength."
    E["T6A04"] = "A capacitor stores energy in an electric field between its plates. When voltage is applied, charge builds up on the plates, storing energy. Capacitors are used for filtering, coupling, timing, and energy storage throughout electronics."
    E["T6A05"] = "A capacitor is made of conductive surfaces, or plates, separated by an insulator called the dielectric. Charge collects on the plates, and the energy is stored in the electric field between them. Resistors and potentiometers oppose current flow, and an oscillator is a circuit that generates a signal, not a component built this way."
    E["T6A06"] = "An inductor stores energy in a magnetic field. When current flows through the coil, a magnetic field forms around it, storing energy. This is the fundamental operating principle of inductors, transformers, and many RF circuits."
    E["T6A07"] = "An inductor is typically constructed as a coil of wire. The coil shape concentrates the magnetic field and increases the inductance. Adding a ferromagnetic core (like iron) further increases the inductance."
    E["T6A08"] = "SPDT stands for single-pole, double-throw. Single pole means one circuit is being switched, and double throw means that circuit can be connected to either of two other circuits. Choice A describes a single-pole, single-throw on-off switch, and choices B and D describe double-pole switches, which handle two circuits at once."
    E["T6A09"] = "Component 3 in figure T-2 represents a single-pole single-throw (SPST) switch. SPST is the simplest switch type — it either connects or disconnects a single circuit path. One pole (connection point), one throw (position)."
    E["T6A10"] = "Nickel-metal hydride, lithium-ion, and lead-acid are all rechargeable, or secondary, battery chemistries. Nickel-metal hydride is common in rechargeable AA and AAA cells, lithium-ion powers handheld radios and phones, and lead-acid is the car battery that's also popular for station backup power. Since all three are rechargeable, the answer is all these choices are correct."
    E["T6A11"] = "Carbon-zinc cells are primary, or disposable, batteries and are not designed to be recharged. Trying to recharge them can make them leak or rupture. Nickel-cadmium, lead-acid, and lithium-ion are all rechargeable chemistries."

    # ── T6B ──────────────────────────────────────────────────────────
    E["T6B01"] = "Forward voltage drop depends on the diode type. A silicon diode drops about 0.7 volts, while germanium and Schottky diodes drop less, around 0.2 to 0.3 volts. That drop is normal and doesn't mean the diode is defective. It also isn't proportional to peak inverse voltage, and it does reduce the voltage delivered to the load."
    E["T6B02"] = "A diode works like a one-way valve, letting current flow in only one direction, from anode to cathode, and blocking it the other way. A resistor opposes current in both directions, and a fuse opens to protect a circuit when the current gets too high. A driven element is part of an antenna, not a circuit component."
    E["T6B03"] = "A transistor's main function is to amplify or switch electronic signals. It's the fundamental building block of modern electronics — every computer chip contains billions of transistors. In amateur radio, transistors amplify RF signals in receivers and transmitters."
    E["T6B04"] = "A transistor consists of three regions of semiconductor material. In a bipolar junction transistor (BJT), these are the emitter, base, and collector. In a field-effect transistor (FET), they're the source, gate, and drain."
    E["T6B05"] = "A field-effect transistor (FET) has a gate, drain, and source. This distinguishes it from a bipolar transistor, which has a base, collector, and emitter. FETs are widely used in receivers because of their high input impedance."
    E["T6B06"] = "The cathode end of a semiconductor diode is usually marked with a stripe or band around the package. The stripe matches the bar at the cathode end of the diode's schematic symbol. Diodes are usually too small to print the word cathode or a letter on them, so the stripe is the standard marking."
    E["T6B07"] = "An LED emits light due to forward current flowing through the semiconductor junction. When electrons cross the junction and recombine, they release energy as photons (light). The color depends on the semiconductor material used."
    E["T6B08"] = "FET stands for field effect transistor. The voltage on its gate creates an electric field that controls the current flowing between the source and the drain. The other choices are made-up phrases, and a FET is a transistor, not a transmitter."
    E["T6B09"] = "The two electrodes of a diode are the anode and the cathode. When the diode is forward biased, current flows from anode to cathode. Source, drain, and gate are field-effect transistor terminals, and base belongs to a bipolar transistor. Plus and minus describe polarity, not the names of the electrodes."
    E["T6B10"] = "A transistor can provide power gain: a small input signal controls a larger current drawn from the power supply, so the output can have more power than the input. A transformer can raise voltage, but only by lowering current, so it never adds power. Resistors and reactors only oppose current and can't add power to a signal."
    E["T6B11"] = "In amplifiers, the term \"gain\" refers to the ratio of the output signal to the input signal — it can describe voltage gain, current gain, or power gain. All of these are valid meanings of gain in the context of amplifiers."
    E["T6B12"] = "The three electrodes of a bipolar junction transistor are the emitter, base, and collector. The base controls the current flow between the emitter and collector. In an NPN transistor, a small current into the base allows a much larger current to flow from collector to emitter, and that's how transistors amplify."

    # ── T6C ──────────────────────────────────────────────────────────
    E["T6C01"] = "An electrical diagram using standard component symbols is called a schematic. Schematics use standardized symbols to represent resistors, capacitors, transistors, and other components, showing how they're connected. It's the universal language of electronics."
    E["T6C02"] = "Component 1 in figure T-1 is a resistor. The zigzag symbol is the standard schematic representation for a resistor. Recognizing common schematic symbols is an important skill for any electronics work."
    E["T6C03"] = "Component 2 in figure T-1 is a transistor. The symbol shows the characteristic three-terminal device with its distinctive arrow indicating current direction. Learning to identify transistor symbols in schematics is fundamental."
    E["T6C04"] = "Component 3 in figure T-1 is a lamp, or light bulb. It's drawn as a rounded bulb outline, like an upside-down U, with a small loop inside that represents the filament. Don't confuse it with the transistor, component 2, which is the symbol drawn inside a full circle."
    E["T6C05"] = "Component 4 in figure T-1 is a battery. The alternating long and short lines represent multiple cells — the long line is positive and the short line is negative."
    E["T6C06"] = "Component 6 in figure T-2 is a capacitor. The two parallel lines (or one curved line and one straight) represent a capacitor in schematic diagrams."
    E["T6C07"] = "Component 8 in figure T-2 is a light-emitting diode (LED). The diode symbol with arrows pointing away (representing emitted light) is the standard LED symbol."
    E["T6C08"] = "Component 9 in figure T-2 is a variable resistor. It's drawn as a zigzag resistor with an arrow, called a wiper, pointing at the side of the zigzag and wired back to one end, which lets you adjust the resistance. A variable capacitor would show capacitor plates with an arrow, and a variable inductor would show a coil."
    E["T6C09"] = "Component 4 in figure T-2 is a transformer. It's drawn as two coils facing each other with two parallel lines between them, which represent the iron core. A variable inductor would be a single coil with an arrow, a potentiometer is a zigzag resistor with an arrow, and a double-pole switch would show two switch blades."
    E["T6C10"] = "Component 3 in figure T-3 is a variable inductor. It's drawn as a coil of loops with an arrow touching the side of the coil, a sliding tap wired to the coil's bottom end, which changes how much of the coil is in use. Don't confuse it with the variable capacitors in the same figure, which are two parallel plates with a diagonal arrow through them. A connector and a meter use entirely different symbols."
    E["T6C11"] = "Component 4 in figure T-3 is an antenna. Its symbol is an upside-down triangle sitting on top of a vertical line, at the output of this tuning circuit. A ground is the set of short slanted lines at the bottom of the coil in the same figure, and transmitters and dummy loads are drawn differently."
    E["T6C12"] = "A schematic accurately shows component connections, meaning which parts are wired to which, using standard symbols. It doesn't show how long the wires are or what the parts physically look like, so all these choices are correct is wrong. Think of a schematic as a logical map of the circuit, not a picture of it."

    # ── T6D ──────────────────────────────────────────────────────────
    E["T6D01"] = "A rectifier changes alternating current into a varying, or pulsating, direct current by letting current flow in only one direction, usually with diodes. A transformer changes one AC voltage to another, but its output is still AC. An amplifier increases a signal's strength, and a reflector is part of an antenna."
    E["T6D02"] = "A relay is an electrically-controlled switch: an electromagnet that physically opens or closes a set of contacts. When current flows through the relay's coil, the magnetic field pulls the contacts closed, or open. Relays let a small control signal switch a larger power circuit. A relay is not an amplifier or a pass transistor."
    E["T6D03"] = "Shielded wire prevents unwanted signals from coupling to or from the wire. The shield acts as a barrier to external RF fields, keeping interference out and keeping the wire from radiating like an antenna. It doesn't lower DC resistance or raise current-carrying capability, and it isn't the cure for receiver overload, which comes from strong signals reaching the receiver's input."
    E["T6D04"] = "A meter, such as a digital voltmeter or multimeter, displays an electrical quantity like voltage, current, or resistance as a numeric value. A potentiometer is a variable resistor, a transistor is a switch or amplifier, and a relay is an electrically controlled switch. None of those displays anything."
    E["T6D05"] = "A voltage regulator controls the amount of voltage from a power supply. It holds the output steady even when the input voltage or the load changes. An oscillator generates a signal, a filter removes unwanted frequencies or ripple, and a phase inverter flips a signal's phase, but none of them sets the output voltage."
    E["T6D06"] = "A transformer changes 120 volt AC power to a lower AC voltage. It has two coils wound on a shared core. AC in the primary coil creates a changing magnetic field that induces a voltage in the secondary, and the ratio of turns sets the output voltage. A variable capacitor, a transistor, and a diode can't step AC voltage down this way, though a diode is often used afterward to turn the AC into DC."
    E["T6D07"] = "An LED, or light-emitting diode, is the standard visual indicator for power, transmit, and status lights because it's bright, efficient, and long-lasting. A FET is a transistor used for switching and amplifying, and a Zener diode regulates voltage, and neither gives off light. That also rules out all these choices are correct."
    E["T6D08"] = "An inductor combined with a capacitor makes a resonant, or tuned, circuit. At the resonant frequency, energy swaps back and forth between the inductor's magnetic field and the capacitor's electric field. A resistor or potentiometer only uses up energy, and a Zener diode is used to regulate voltage, so none of them can form a resonant circuit with an inductor."
    E["T6D09"] = "An integrated circuit, or IC, combines many semiconductors such as transistors and diodes, along with other components such as resistors, into one package. A transducer converts one form of energy into another, the way a microphone does. A multi-pole relay is a switch, and a transformer is a pair of magnetically coupled coils."
    E["T6D10"] = "Component 2 in figure T-1 is a transistor, drawn as a circle containing a bar with two angled leads, one with an arrow. Its function is to control the flow of current: a small signal through the resistor into its base controls a larger current through the lamp. The lamp, component 3, is what gives off light, and the battery, component 4, supplies the electrical energy. Turning electrical energy into radio waves is the antenna's job."
    E["T6D11"] = "A resonant, or tuned, circuit is an inductor and a capacitor connected either in series or in parallel. It responds strongly at one frequency, which is how a radio picks out one station. A voltage regulator holds voltage steady, and resistor networks and audio circuits don't have the inductor and capacitor pair that makes resonance possible."

    # ── T7A ──────────────────────────────────────────────────────────
    E["T7A01"] = "Sensitivity describes a receiver's ability to detect the presence of weak signals. A more sensitive receiver can pick up fainter signals. Sensitivity is typically measured in microvolts — the lower the number, the more sensitive the receiver."
    E["T7A02"] = "A transceiver combines a receiver and a transmitter in one unit, sharing circuits like frequency control and the power supply. Almost all modern amateur radios are transceivers. Matching feed line impedance is the job of an antenna tuner, and converting to another band is what a transverter does."
    E["T7A03"] = "A mixer converts a signal from one frequency to another by combining it with a local oscillator signal. The mixer produces sum and difference frequencies — this frequency conversion is at the heart of the superheterodyne receiver design used in virtually all modern radios."
    E["T7A04"] = "Selectivity is a receiver's ability to separate the signal you want from other signals on nearby frequencies, mostly thanks to its filters. Sensitivity is a different property, the ability to detect weak signals. Discrimination ratio sounds right but isn't the standard term, and harmonic distortion is about signal purity."
    E["T7A05"] = "An oscillator is a circuit that generates a signal at a specific frequency, and every transmitter and receiver uses one. Reactance and phase modulators change an existing signal rather than create one, and a low-pass filter only passes or blocks frequencies."
    E["T7A06"] = "A transverter converts a transceiver's RF input and output to another band, for example letting a 10-meter or 2-meter radio operate on a higher band. It converts both the transmitted and the received signals. High-pass and low-pass filters only pass or block frequencies without changing them, and a phase converter is electrical power equipment, not a radio device."
    E["T7A07"] = "PTT stands for push to talk. Grounding the PTT input, usually by pressing the microphone button, switches the transceiver from receive to transmit. A CW key plugs into a separate key jack, and the PTT line doesn't generate any tuning tones."
    E["T7A08"] = "Modulation is the process of combining speech, data, or other information with an RF carrier signal. AM, FM, and single sideband are all types of modulation. Oscillation creates the carrier in the first place, impedance matching helps transfer power to the antenna, and low-pass filtering removes higher frequencies."
    E["T7A09"] = "The SSB/CW-FM switch on VHF power amplifiers sets the amplifier for proper operation in the selected mode. SSB and CW need linear amplification to preserve the signal's amplitude variations, while FM can use more efficient non-linear amplification."
    E["T7A10"] = "An RF power amplifier (or linear amplifier) can be added to the output of a transceiver to increase transmitted power. It boosts the transmitter's signal before it reaches the antenna."
    E["T7A11"] = "The Variable Frequency Oscillator (VFO) circuit in a transceiver sets the receive and transmit frequency. By adjusting the VFO, you tune across the band. The VFO determines what frequency you're operating on — it's the tuning heart of the radio."

    # ── T7B ──────────────────────────────────────────────────────────
    E["T7B01"] = "If your FM handheld or mobile is over-deviating, you're talking too loudly or too close to the microphone. Back away from the mic and speak at a normal conversational level. Over-deviation causes distorted, hard-to-understand audio on the receiving end."
    E["T7B02"] = "If a broadcast AM or FM radio is receiving your amateur transmissions, the problem is fundamental overload — the consumer receiver can't reject your strong nearby signal because it has poor front-end filtering. The issue is with their receiver, not your transmitter."
    E["T7B03"] = "All three can cause radio frequency interference. Fundamental overload happens when a strong signal overwhelms a nearby receiver, harmonics are multiples of your transmit frequency that can land on other services, and spurious emissions are other unwanted signals from a transmitter. Since all three apply, D is correct."
    E["T7B04"] = "A high SWR can cause low RF power output from a solid-state transceiver. When the antenna system presents a poor match (high SWR), most modern radios automatically reduce power to protect their output transistors. Fix the antenna match to restore full power."
    E["T7B05"] = "To reduce interference to a non-amateur over-the-air radio receiver, you can install a filter at the receiver's antenna input. A filter that passes only the desired broadcast frequencies and rejects your amateur signal addresses the fundamental overload problem."
    E["T7B06"] = "Start by checking your own station. Make sure it's working properly, and see whether it interferes with your own radio or TV tuned to the same channel. If your own equipment is clean, the problem may be in the neighbor's receiver. There's no need to shut down and call the FCC right away, and a harmonic doubler would make interference worse, not better."
    E["T7B07"] = "A band-reject filter tuned to the interfering commercial FM frequency can reduce interference to a 2-meter transceiver from a nearby commercial FM station. The filter notches out the specific frequency causing the problem while passing your amateur signals."
    E["T7B08"] = "All three are correct. Work with your neighbor to find the offending device, politely explain that FCC rules prohibit using devices that cause harmful interference, and make sure your own station meets the standards of good amateur practice. A friendly, cooperative approach works far better than confrontation."
    E["T7B09"] = "The first step is to make sure all the TV feed line coaxial connectors are installed properly. Loose or poorly installed connectors let RF leak into the cable system, which is a common cause of cable TV interference. Check that easy fix before adding filters, and never add a preamplifier, which would only amplify the problem."
    E["T7B10"] = "All three can cause distorted FM audio through a repeater. Being slightly off frequency can distort your signal in the repeater's receiver, speaking too loudly or too close to the microphone over-deviates your signal, and a bad location causes multipath or weak-signal problems. Since all three apply, D is correct."
    E["T7B11"] = "Adding a clip-on ferrite \"choke\" to the microphone cable can eliminate distorted voice transmissions caused by RF feedback. The ferrite prevents the transmitted RF signal from traveling back along the mic cable and feeding back into the transmitter's audio input."

    # ── T7C ──────────────────────────────────────────────────────────
    E["T7C01"] = "A dummy load is used in place of an antenna for testing a transmitter without radiating a signal. It absorbs the transmitter's power as heat, letting you test and tune without causing interference. Every well-equipped station should have one."
    E["T7C02"] = "An antenna analyzer measures an antenna's impedance and SWR across a range of frequencies, so it shows you where the antenna is resonant. A frequency counter only measures the frequency of a signal, a VTVM is a type of voltmeter, and a Q meter tests components, not antennas."
    E["T7C03"] = "A typical RF dummy load consists of a 50-ohm non-inductive resistor mounted on a heat sink. The non-inductive design ensures it presents a pure 50-ohm load at radio frequencies. The heat sink dissipates the power as heat."
    E["T7C04"] = "An SWR reading of 1 to 1 means a perfect match. The antenna's impedance equals the feed line's, and no power is reflected back toward the transmitter. SWR can never be less than 1 to 1, so a reading of zero isn't possible, and 50 to 50 isn't how SWR is expressed."
    E["T7C05"] = "Most solid-state transmitters automatically reduce output power as SWR increases to protect the RF output amplifier transistors. Excessive reflected power can overheat and destroy the output transistors. The fold-back circuit is a safety mechanism."
    E["T7C06"] = "An SWR of 4 to 1 indicates an impedance mismatch between the antenna system and the feed line. A good match is close to 1 to 1. SWR is a ratio, not a gain or loss in decibels, so the choices with dB values are wrong."
    E["T7C07"] = "Power lost in a feed line is converted into heat in the conductors and the insulating material. It isn't radiated as harmonics, and feed line loss doesn't increase the SWR. In fact, loss makes the SWR measured at the transmitter look better than it really is at the antenna."
    E["T7C08"] = "A directional wattmeter measures both forward and reflected power, and from those two readings you can determine the SWR. A voltmeter and an ohmmeter can't separate forward power from reflected power. Iambic pentameter is a joke answer. It's a rhythm used in poetry, not a radio instrument."
    E["T7C09"] = "Moisture contamination is the main cause of coaxial cable failure. Water gets in through a damaged jacket or a poorly sealed connector, increases the cable's loss, and corrodes the conductors. That's why outdoor connectors should always be weatherproofed. Power changes and long transmissions don't harm coax that's used within its ratings."
    E["T7C10"] = "Coaxial cable's outer jacket must be resistant to UV light because ultraviolet radiation degrades the jacket material, allowing moisture to enter the cable. Moisture inside coax dramatically increases signal loss and can destroy the cable."
    E["T7C11"] = "Foam-dielectric coaxial cable has less loss per foot compared to solid-dielectric types. The foam dielectric has a lower effective dielectric constant, which reduces signal loss. The trade-off is that foam cable is more susceptible to moisture contamination."

    # ── T7D ──────────────────────────────────────────────────────────
    E["T7D01"] = "A voltmeter is used to measure electric potential (voltage). It's connected in parallel across the component or circuit you want to measure. A voltmeter should have high input impedance to avoid disturbing the circuit."
    E["T7D02"] = "A voltmeter is connected in parallel, which means across the component, so it can measure the voltage difference between its two ends. A good voltmeter draws very little current, so it barely disturbs the circuit. A series connection is used for measuring current, and in quadrature and in phase describe the timing between AC signals, not how meters are connected."
    E["T7D03"] = "To measure current, the multimeter is connected in series, so all the current flowing through the component also flows through the meter. That usually means opening the circuit and inserting the meter. A meter set for current has very low resistance, so connecting it in parallel can short the circuit and blow the meter's fuse."
    E["T7D04"] = "An ammeter measures electric current, in amperes, and is connected in series with the circuit. A voltmeter measures voltage and an ohmmeter measures resistance. An electrometer is a specialized laboratory instrument for measuring charge and tiny currents or voltages in very high-impedance circuits; it isn't the everyday tool for measuring current."
    E["T7D05"] = "An ohmmeter measures resistance by applying a small known current from its internal battery and measuring the resulting voltage across the component under test. Using Ohm's Law (R = E/I), the meter calculates and displays the resistance. This is why you need to disconnect the component — the meter's own current must be the only current flowing through it."
    E["T7D06"] = "Measuring voltage with the meter set to resistance can damage a multimeter. In resistance mode the meter sends its own small current through the circuit, and an outside voltage can overload those sensitive circuits. The reverse mistake, measuring resistance on a voltage setting, just gives a useless reading. Multimeters don't need to warm up, and neither probe has to be connected to ground."
    E["T7D07"] = "A multimeter measures voltage, current, and resistance, so voltage and resistance is the right choice. Signal strength and noise need a receiver or spectrum analyzer, and impedance and reactance at radio frequencies need an instrument like an antenna analyzer. Because those two choices are wrong, all these choices is wrong too."
    E["T7D08"] = "Acid-core solder should never be used for radio and electronics work. Its acid flux is corrosive and will eat away at wires, components, and circuit boards over time. Use rosin-core solder instead. Lead-tin and tin-copper describe the solder metal itself, and both are used in electronics."
    E["T7D09"] = "A cold tin-lead solder joint has a rough, grainy, or dull gray appearance. Good solder joints are smooth and shiny. If your joint looks grainy or dull, reheat it with the soldering iron and let it flow properly."
    E["T7D10"] = "When you connect an ohmmeter across a large, discharged capacitor, the reading starts low and the resistance increases with time. The meter's internal battery charges the capacitor, so current flows freely at first and then tapers off as the capacitor charges. This makes a handy quick check that a capacitor is charging normally."
    E["T7D11"] = "Before you measure resistance in a circuit, make sure the circuit is not powered. An ohmmeter uses its own internal battery, so any voltage already present will throw off the reading and could damage the meter. Grounding the circuit or checking its voltages or frequency doesn't solve that problem."

    # ── T8A ──────────────────────────────────────────────────────────
    E["T8A01"] = "Single sideband is a form of amplitude modulation. It starts as an AM signal, then the carrier and one sideband are removed, leaving a single sideband to carry the information. Packet radio is a data protocol, and spread spectrum and phase shift keying are different techniques, not forms of amplitude modulation."
    E["T8A02"] = "VHF packet radio is commonly sent using FM or PM, phase modulation, usually by feeding audio tones from a modem into an ordinary FM radio. FM transceivers are inexpensive and widely available on VHF, so they're a natural fit. SSB and AM aren't commonly used for VHF packet, and PSK is a separate digital mode used mostly on HF."
    E["T8A03"] = "SSB is the preferred voice mode for long-distance, weak-signal contacts on VHF and UHF. It puts all of the transmitter's power into one narrow sideband with no carrier, so weak signals can still get through. FM and PM are great for local repeater contacts but need a stronger signal, and DRM is a digital broadcasting format, not a common amateur weak-signal mode."
    E["T8A04"] = "VHF and UHF voice repeaters commonly use FM or PM, phase modulation, which is closely related to FM. FM gives clear audio, resists noise, and suits the channelized repeater frequencies. AM and SSB are seldom used on repeaters, and PSK is a digital data mode, not a voice mode."
    E["T8A05"] = "CW, or Morse code, has the narrowest bandwidth of the choices listed, about 150 hertz. SSB voice is roughly 3 kilohertz, FM voice is about 10 to 15 kilohertz, and analog slow-scan TV is sent within about the same width as an SSB voice signal. CW's narrow bandwidth is one reason it works so well for weak-signal communication."
    E["T8A06"] = "Upper sideband (USB) is normally used for 10-meter HF, VHF, and UHF single-sideband communications. The convention is USB above 10 MHz. Since 10 meters (28 MHz) is above this threshold, USB is the standard."
    E["T8A07"] = "A key characteristic of SSB compared to FM is that SSB signals have a narrower bandwidth, which means they can be heard under noisier conditions and at greater distances with lower power."
    E["T8A08"] = "The approximate bandwidth of an SSB voice signal is about 3 kHz. This is much narrower than FM's 10–15 kHz bandwidth, which is one reason SSB is more efficient for long-distance communication."
    E["T8A09"] = "The approximate bandwidth of a VHF repeater FM voice signal is between 10 and 15 kHz. FM uses more bandwidth than SSB, but provides cleaner, noise-free audio above the squelch threshold."
    E["T8A10"] = "The typical bandwidth of an analog fast-scan TV (NTSC) signal on the 70-centimeter band is about 6 MHz. Amateur TV uses the same NTSC standard as broadcast television, which requires a wide bandwidth."
    E["T8A11"] = "A CW signal needs only about 150 hertz of bandwidth, much narrower than any voice mode. About 2.4 kilohertz is what an SSB voice signal uses, and 15 kilohertz is the width of an FM voice signal. 1000 hertz is also far more than a clean CW signal needs."
    E["T8A12"] = "Because of FM's capture effect, the strongest signal on a frequency takes over the receiver and weaker ones are suppressed, so only one signal can be received at a time. With SSB, you can hear several stations on the same frequency at once. FM's voice quality is generally good, and FM is actually easier to tune in than SSB."

    # ── T8B ──────────────────────────────────────────────────────────
    E["T8B01"] = "Satellite beacons typically send telemetry about the health and status of the satellite, such as battery voltage, temperatures, and the condition of its systems. Ground stations use this data to keep an eye on the spacecraft. Reporting the strength of your signal and sending precise time are not what beacons are typically for, so all these choices is wrong."
    E["T8B02"] = "Using too much effective radiated power on a satellite uplink can block access by other users. A satellite's transponder shares its limited power among everyone using it, so an overly strong signal takes more than its share and drowns out others. Use only enough power to be heard. Too much uplink power doesn't overload the satellite's batteries or reboot its computer."
    E["T8B03"] = "Satellite tracking programs provide all three. They show a map of the satellite's real-time position over Earth, the time, azimuth, and elevation for the start, highest point, and end of each pass, and the apparent frequency corrected for Doppler shift. Since all three apply, D is correct."
    E["T8B04"] = "Amateur satellites use many modes. Linear transponders carry SSB and CW, many satellites have FM repeaters, and others relay digital data. Since all three apply, D is correct."
    E["T8B05"] = "A satellite beacon is a transmission from a satellite that contains status information, such as telemetry about its batteries and temperatures. Hearing the beacon also tells you the satellite is in range and working. A beacon isn't an antenna, an indicator light, or a reflective surface."
    E["T8B06"] = "Satellite tracking programs need the Keplerian elements, a set of numbers that describe the satellite's orbit. They're published regularly, often in a format called two-line elements, and should be updated from time to time because orbits slowly change. The program doesn't need the satellite's transmit power or past Doppler observations."
    E["T8B07"] = "Doppler shift is an observed change in signal frequency caused by relative motion between the satellite and your Earth station. As a satellite approaches, its signal appears higher in frequency, and as it moves away, the frequency drops, much like the pitch of a passing siren. It isn't an orbit change, a band mode, or a digital mode, and you adjust your frequency during a pass to compensate."
    E["T8B08"] = "In U/V mode, the satellite's uplink is in the 70-centimeter band, which is UHF, and its downlink is in the 2-meter band, which is VHF. The first letter is the uplink and the second is the downlink. It has nothing to do with ultraviolet light, and the 15- and 10-meter bands are HF, which use different letters."
    E["T8B09"] = "Spin fading is caused by rotation of the satellite and its antennas. As the satellite spins or tumbles, its antennas point toward you and then away, so the signal fades in and out in a regular rhythm. It's different from Doppler shift, which changes the frequency, and it isn't caused by noise from the sun."
    E["T8B10"] = "LEO stands for Low Earth Orbit — a satellite orbiting relatively close to Earth, typically at altitudes below about 2,000 km. LEO satellites have orbital periods of around 100 minutes, which means they pass over any given point relatively quickly."
    E["T8B11"] = "Anyone may receive telemetry from an amateur radio satellite. There are no restrictions on receiving — you don't need special authorization, a specific license class, or a decryption key. If you can hear it, you can listen."
    E["T8B12"] = "To determine if your satellite uplink power into a linear transponder satellite is correct, compare your downlink signal strength to the satellite's beacon signal. Your signal should be about the same strength as the beacon — not stronger, not weaker."

    # ── T8C ──────────────────────────────────────────────────────────
    E["T8C01"] = "Radio direction finding is used to locate sources of noise interference or jamming. With a directional antenna, you take bearings on the signal from different spots and follow it back to the source. Echolocation and Doppler radar detect objects with reflected signals, and phase locking is a way to keep an oscillator on frequency."
    E["T8C02"] = "A directional antenna is the key tool for a hidden transmitter hunt, also called a fox hunt. Turning the antenna shows you the direction where the signal is strongest, and bearings taken from several spots lead you to the transmitter. An SWR meter and a directional wattmeter measure your own antenna system, not the direction of an incoming signal, so all these choices is wrong."
    E["T8C03"] = "Contesting is the operating activity that involves contacting as many stations as possible during a specified period. Contests (also called radiosport) are competitive events where operators try to make the most contacts, sometimes over a weekend."
    E["T8C04"] = "Good practice in a contest is sending only the minimum information needed for proper identification and the contest exchange. Be efficient — don't waste time with extended conversations. Get the call sign, exchange, and move on to the next contact."
    E["T8C05"] = "A grid locator is a letter-number designator assigned to a geographic location. The Maidenhead grid system divides the world into grid squares, and your grid square identifies your approximate location for VHF/UHF contests and awards."
    E["T8C06"] = "Over-the-air access to IRLP (Internet Radio Linking Project) nodes is accomplished by using DTMF (Dual-Tone Multi-Frequency) signals. You dial DTMF codes from your radio to connect to or disconnect from IRLP nodes."
    E["T8C07"] = "VoIP, or Voice over Internet Protocol, is a method of delivering voice communications over the internet using digital techniques. Amateur linking systems such as EchoLink, IRLP, and AllStar use VoIP to connect repeaters and stations around the world. It isn't an identification rule, a DX spotting method, or a way to measure modulation quality."
    E["T8C08"] = "IRLP (Internet Radio Linking Project) is a technique to connect amateur radio systems, such as repeaters, via the internet. It lets you talk through a local repeater and be heard on a linked repeater hundreds or thousands of miles away."
    E["T8C09"] = "EchoLink lets you connect to repeaters and other stations from a computer or smartphone, so you can transmit through a repeater without using a radio to start the transmission. IRLP users get on the system over the air with a radio. D-STAR and DMR are digital voice modes that are normally used with radios."
    E["T8C10"] = "Before using the EchoLink system, you need a valid amateur radio license and proof of licensure. EchoLink verifies your license to prevent unlicensed use of the system."
    E["T8C11"] = "A gateway is an amateur station that connects other amateur stations to the internet, acting as a bridge between radio and the internet. A repeater retransmits signals on another frequency, a digipeater relays digital packets over the air, and a beacon transmits so others can check propagation or equipment."

    # ── T8D ──────────────────────────────────────────────────────────
    E["T8D01"] = "All three are digital communications modes. Packet radio sends data in packets, IEEE 802.11 is the Wi-Fi standard that hams use in mesh networks, and FT8 is a popular weak-signal digital mode. Since all three are digital, D is correct."
    E["T8D02"] = "FT8 is a digital mode capable of low signal-to-noise operation. It's designed for making contacts when signals are extremely weak — stations can communicate even when the signals are far below what the human ear can detect. FT8 has become enormously popular for HF contacts."
    E["T8D03"] = "APRS, the Automatic Packet Reporting System, can carry all of these: GPS position data, short text messages, and weather data from weather stations. That's what makes it so useful for tracking and public service events. Since all three apply, D is correct."
    E["T8D04"] = "NTSC is an analog video standard used for amateur fast-scan television (ATV). It's the same system that was used for broadcast television in North America. It requires about 6 MHz of bandwidth."
    E["T8D05"] = "APRS (Automatic Packet Reporting System) can automatically report your station's location, show it on a map, and transmit weather station data. It's a tactical communication system used for real-time position tracking and situational awareness."
    E["T8D06"] = "PSK stands for Phase Shift Keying — a digital modulation method that encodes data by shifting the phase of the carrier signal. PSK31 is a popular amateur digital mode that uses very narrow bandwidth."
    E["T8D07"] = "DMR, or Digital Mobile Radio, uses time-division multiplexing to carry two separate digital voice signals on a single 12.5 kilohertz repeater channel. The two time slots alternate rapidly, so one repeater can carry two conversations at once. It isn't a position tracking system, a logging method, or a way to transmit on two repeater inputs."
    E["T8D08"] = "Packet radio transmissions include all three. A checksum lets the receiving station detect errors, a header carries the call sign of the station the data is going to, and automatic repeat request, or ARQ, asks for any packet received with errors to be sent again. Since all three apply, D is correct."
    E["T8D09"] = "CW stands for Continuous Wave, which is Morse code transmission using on-off keying of an unmodulated carrier. It's the oldest digital mode and still one of the most efficient for weak-signal communication."
    E["T8D10"] = "The WSJT-X software suite supports all three activities. It has modes for Earth-Moon-Earth contacts, such as JT65 and Q65, for weak signal propagation beacons, such as WSPR, and for meteor scatter, such as MSK144. Since all three are supported, D is correct."
    E["T8D11"] = "ARQ (Automatic Repeat reQuest) is a technique where the receiving station detects errors and requests retransmission of corrupted data. This ensures reliable data delivery over a potentially noisy radio channel."
    E["T8D12"] = "An amateur radio mesh network is a data network using commercial Wi-Fi equipment with modified firmware to operate on amateur frequencies. It creates a self-healing, multi-node network for data communications, useful for emergency communications and community networking."

    # ── T9A ──────────────────────────────────────────────────────────
    E["T9A01"] = "A beam antenna is a directional antenna that concentrates its signal in one direction for increased gain. Yagi-Uda arrays and quad antennas are common types. By focusing energy in one direction, beam antennas provide more gain than omnidirectional designs."
    E["T9A02"] = "Antenna loading means adding a coil (an inductor) to the radiating element so a physically short antenna acts electrically longer and becomes resonant at a lower frequency. That is how short mobile HF whips work on bands where a full-size antenna would be far too long. A resistor would just waste power as heat, and a base spring or stronger elements are mechanical changes, not loading."
    E["T9A03"] = "Antenna polarization is described by the orientation of the electric field. If the electric field oscillates vertically, the antenna is vertically polarized. If horizontally, it's horizontally polarized. Matching polarization between stations maximizes signal transfer."
    E["T9A04"] = "The short flexible antenna (rubber duck) on a handheld has less efficient radiation and lower gain compared to a full-sized quarter-wave antenna. The rubber duck is convenient but compromises performance — it doesn't radiate as effectively because it's much shorter than optimal."
    E["T9A05"] = "A dipole's resonant frequency goes up as it gets shorter, because frequency and length are inversely related. With the dipole formula, length in feet equals 468 divided by frequency in megahertz, so a 33-foot dipole resonates near 14.2 megahertz, and trimming it to 32 feet raises that to about 14.6 megahertz. Lengthening it, adding series coils, or adding capacitive loading at the ends all make it electrically longer, which lowers the resonant frequency instead."
    E["T9A06"] = "A Yagi antenna offers the greatest gain among common amateur antennas. Its multiple elements (driven element, reflector, and directors) work together to focus energy in one direction, providing significant gain over a simple dipole."
    E["T9A07"] = "Using a handheld VHF transceiver inside a vehicle without an external antenna is problematic because the vehicle's metal body significantly attenuates the signal, reducing both transmitted and received signal strength. An external antenna mounted on the vehicle is much more effective."
    E["T9A08"] = "A 19-inch vertical is a resonant quarter-wave on 2 meters. The quarter-wave formula gives length in feet: 234 divided by 146 megahertz is about 1.6 feet, and 1.6 feet times 12 is about 19 inches. A half-wave would be about twice that long, and the length has nothing to do with high gain or low RF exposure. A quarter-wave vertical is one of the simplest and most practical antennas for VHF."
    E["T9A09"] = "A 5/8-wavelength whip antenna for VHF or UHF mobile service has more gain than a 1/4-wave antenna. The 5/8-wave design concentrates more of its radiation toward the horizon rather than upward, which is exactly what you want for mobile ground-to-ground communication."
    E["T9A10"] = "A half-wave dipole radiates most strongly broadside, meaning at right angles to the wire. Its pattern looks like a donut around the wire, with deep nulls off the ends. So it is not equally strong in all directions, it is weakest off the ends, and the feed line direction has nothing to do with it."
    E["T9A11"] = "Antenna gain is the increase in signal strength in a particular direction compared to a reference antenna, such as an isotropic radiator (dBi) or a dipole (dBd). An antenna can't add power; it gets gain by concentrating the power it already has toward some directions and away from others. That is why the answers about added power or increased impedance are wrong."

    # ── T9B ──────────────────────────────────────────────────────────
    E["T9B01"] = "All RF connectors used outdoors — PL-259, Type N, and BNC — should be carefully taped or sealed for weather protection. Moisture in any connector causes corrosion and signal loss. Use self-fusing silicone tape or commercial weatherproofing kits."
    E["T9B02"] = "The characteristic impedance of most common amateur radio coaxial cable is 50 ohms. This is the standard impedance for amateur radio — 75-ohm cable is used for TV and cable systems, but amateur equipment is designed for 50 ohms."
    E["T9B03"] = "Coax is the most popular feed line because it's easy to use: you can run it along walls, through windows, near metal, or bundle it with other cables without the careful spacing that open-wire line needs. It is not the lowest-loss feed line; open-wire and ladder line have much less loss than ordinary flexible coax. It doesn't handle the most power, and it isn't always the cheapest either. Convenience is the reason."
    E["T9B04"] = "An antenna tuner, or antenna coupler, transforms the impedance of the antenna system into the 50 ohms your transceiver expects, so the radio sees a good match and can deliver full power. It doesn't fix the antenna itself; the mismatch is still there on the antenna side of the tuner. It doesn't tune in weak stations, switch between transmit and receive, or pick antennas for you."
    E["T9B05"] = "As frequency goes up, the loss in coaxial cable goes up too. Conductor losses from skin effect and losses in the insulating dielectric both grow with frequency, which is why the same cable that's fine on HF can be quite lossy at 440 megahertz. The characteristic impedance, such as 50 ohms, is set by the cable's dimensions and dielectric and stays essentially the same, so the impedance choices are wrong."
    E["T9B06"] = "Type N connectors are most suitable for frequencies above 400 MHz. They maintain consistent impedance at UHF and above, unlike PL-259 connectors whose performance degrades at higher frequencies."
    E["T9B07"] = "PL-259 plugs and their SO-239 sockets are the most common connectors on amateur gear, and they're widely used at HF and VHF. They are not preferred for microwaves because their impedance isn't constant, so Type N or SMA connectors are used up there. They aren't watertight, so they must be sealed outdoors, and they screw on with a threaded coupling rather than the bayonet twist-lock of a BNC."
    E["T9B08"] = "All three are real sources of loss in a coax feed line. Water that gets into connectors soaks into the cable and sharply increases loss. High SWR adds loss because reflected power travels back and forth through the lossy cable. And every connector or adapter in the line adds a little loss of its own, so the best answer is all of these."
    E["T9B09"] = "Erratic SWR, meaning readings that jump around, points to a loose or intermittent connection in the antenna or feed line, such as a loose connector, a broken conductor, or a bad solder joint that makes and breaks contact. As the contact changes, the impedance the transmitter sees changes, so the SWR reading changes with it. A fault that doesn't change, such as a wrong-length antenna, gives a steady high SWR instead. Thunderstorms, over-modulation, and a strong local station don't change the antenna's match."
    E["T9B10"] = "RG-213 has less loss than RG-58 at any given frequency, because it's a much thicker cable with a larger center conductor and more dielectric between the conductors. Both are 50-ohm cables with a single braided shield, so the claim that RG-58 has two shields is false. RG-213 also handles more power, not RG-58. RG-58 is thinner and more flexible, which is fine for short runs."
    E["T9B11"] = "Air-dielectric hardline (rigid or semi-rigid coaxial cable) has the lowest loss of common feed line types. However, it's expensive, heavy, and difficult to install. For most amateur stations, high-quality flexible coax is a practical compromise."
    E["T9B12"] = "Standing wave ratio (SWR) is a measure of how well a load is matched to a transmission line. An SWR of 1:1 is a perfect match — all power goes to the antenna. Higher SWR means more power is reflected back toward the transmitter, reducing efficiency and potentially damaging equipment."

    for qid in FALLBACK_EXPLANATION_IDS:
        E[qid] = ""

    # fmt: on


RULE_CITATION_RE = re.compile(r"^\[[^\]]+\]\s*")


def build_fallback_explanation(q: dict) -> str:
    """Generate a safe explanation that always matches the current question."""
    answer = q["answers"][q["correct"]]
    question = RULE_CITATION_RE.sub("", q["question"]).strip()
    q_lower = question.lower()

    if answer == "All these choices are correct":
        return "All of the listed choices are correct for this question, so D is the right answer."

    if q["group"].startswith("T5B"):
        return f"This is a unit-conversion or decibel question. Work it out and you get {answer}."

    if q["group"].startswith(("T5C", "T5D")) and any(ch.isdigit() for ch in question):
        return f"Apply the appropriate circuit formula and you get {answer}."

    if q["group"].startswith("T6C"):
        return f"{answer} is the component or connection shown in the referenced figure."

    if q["group"].startswith("T7D"):
        return f"{answer} is the correct measurement method, tool, or precaution here."

    if q_lower.startswith(("what is ", "what are ")):
        return f"The correct answer is {answer}."

    if q_lower.startswith(("what does ", "which term", "what term")):
        return f"{answer} is the correct term or definition for this question."

    if q_lower.startswith(("which of the following", "which frequency", "which band", "what type")):
        return f"The correct choice here is {answer}."

    if q_lower.startswith(("where ", "when ", "how ", "why ")):
        return f"The correct answer is {answer}."

    return f"The correct answer is {q['correct']}) {answer}."


def validate_explanations(questions: list[dict]) -> None:
    """Fail fast if the explanation map drifts from the question pool."""
    question_ids = {q["id"] for q in questions}
    explanation_ids = set(EXPLANATIONS)
    missing = sorted(question_ids - explanation_ids)
    orphaned = sorted(explanation_ids - question_ids)

    if missing or orphaned:
        issues = []
        if missing:
            issues.append(f"missing explanation keys: {', '.join(missing)}")
        if orphaned:
            issues.append(f"orphan explanation keys: {', '.join(orphaned)}")
        raise SystemExit("; ".join(issues))


def load_pool() -> dict:
    """Load the 2026-2030 pool JSON."""
    with open(POOL_PATH) as f:
        return json.load(f)


def group_questions(questions: list[dict]) -> dict[str, dict[str, list[dict]]]:
    """Group questions by subelement and then by group.

    Returns: {subelement: {group: [question, ...]}}
    """
    result: dict[str, dict[str, list[dict]]] = defaultdict(lambda: defaultdict(list))
    for q in questions:
        result[q["subelement"]][q["group"]].append(q)
    return result


def format_question(q: dict) -> str:
    """Format a single question as markdown."""
    lines = [f"### {q['id']}"]
    lines.append(f"**{q['question']}**")

    for letter in ("A", "B", "C", "D"):
        text = q["answers"].get(letter, "")
        if not text:
            continue
        if letter == q["correct"]:
            lines.append(f"- **{letter}) {text}** ✅")
        else:
            lines.append(f"- {letter}) {text}")

    explanation = EXPLANATIONS.get(q["id"], "")
    if not explanation:
        explanation = build_fallback_explanation(q)
    lines.append("")
    lines.append(f"> {explanation}")

    return "\n".join(lines)


def generate_subelement_file(
    subelement: str,
    name: str,
    exam_questions: int,
    pool_size: int,
    groups: dict[str, list[dict]],
) -> str:
    """Generate the full markdown file for one subelement."""
    lines = [f"# {subelement} — {name}"]
    lines.append(f"*{exam_questions} questions on the exam from a pool of {pool_size}*")
    lines.append("")

    for group_id in sorted(groups.keys()):
        desc = GROUP_DESCRIPTIONS.get(group_id, group_id)
        lines.append(f"## Group {group_id} — {desc}")
        lines.append("")

        for q in groups[group_id]:
            lines.append(format_question(q))
            lines.append("")

    return "\n".join(lines)


def main() -> None:
    _load_explanations()
    pool = load_pool()
    validate_explanations(pool["questions"])

    subelements_meta = pool["subelements"]
    grouped = group_questions(pool["questions"])

    for sub_id, groups in sorted(grouped.items()):
        meta = subelements_meta.get(sub_id, {})
        name = meta.get("name", sub_id)
        exam_qs = meta.get("exam_questions", 0)
        pool_size = meta.get("pool_size", sum(len(qs) for qs in groups.values()))

        file_stem = SUBELEMENT_FILES.get(sub_id)
        if not file_stem:
            print(f"WARNING: No file mapping for subelement {sub_id}", file=sys.stderr)
            continue

        content = generate_subelement_file(sub_id, name, exam_qs, pool_size, groups)
        OUTPUT_DIR.mkdir(exist_ok=True)
        out_path = OUTPUT_DIR / f"{file_stem}-questions.md"
        out_path.write_text(content)
        print(f"  ✓ {out_path.name} ({pool_size} questions)")

    print(f"\nDone — {len(grouped)} subelement files generated.")


if __name__ == "__main__":
    main()
